window.TAROT_CARDS = [
  // ===== 大阿卡那 Major Arcana (mj00 - mj21) =====
  {
    id: "mj00", img: "mj00.jpg", arcana: "major", rank: "0", name: "愚者", en: "The Fool", glyph: "🃏",
    upright: { kw: "新的开始 / 自由 / 天真", love: "他赤脚踏上新径，你也别急着给缘分定名分。手里那两枝白玫瑰是轻松的好感，不是沉重的聘礼。先约一场能边走边聊的散步，像谷中河水那样自然往前。抬头看太阳的人不会盯着悬崖，初恋的紧张可以放下。包袱挂在杖头就好，别把过往的旧账也背上路。", study: "像少年迈向崖边那样，新方向入门贵在敢开始。杖头只挂一个小包袱，试水期别囤满桌的资料。白狗扑到脚边，学倦了就起身走十分钟再坐回。他仰头迎向朝阳，给好奇也定一个明亮的期限。野草地里花色繁多，每月留半天整理尝到的收获。", career: "空手出发不等于没准备，坦诚与学习力就是新项目的入场券。把行囊往杖头一挂就上路，转岗前先轻装试接小活。崖边脚下是整片山谷，跳出现岗才能看清新的赛道。临行前把粮袋装满，最低保障算清了再谈冒险。日光当头，头三个月多问少承诺，把小事做成闭环。" },
    reversed: { kw: "冒失 / 停滞不前 / 逃避现实", love: "走到崖边还望着天，这一步该低头看路了。白狗在脚边急得跳脚，等你回应的那颗心也一样。先把杖上的旧包袱解开，上一段的情绪别转嫁给眼前人。白玫瑰经不起随意拿捏，想清楚自己要什么再伸手。阳光刺眼的时候，坦白的话比含糊的笑更值得说出口。", study: "莽莽撞撞冲出草地，三分钟热度的计划先拆小。包袱塞满没翻过的资料，倒出来只留一册在手边。悬崖边不该闭眼快走，报新课前先把要求读明白。小狗跳着唤他，你也拉个人每天盯着你坐下。日头升高再走也不迟，把起步时间固定下来。", career: "崖下的风景看着诱人，没算清退路就先别跳。行囊空着上路会缺口粮，离职前留出一笔备用金。白狗能引路，下家的合同条款要找人问明白。少年赤脚怕石子，手续没办完前别急着庆祝。太阳底下没有新鲜事，冲动辞呈的理由写下来再读一遍。" }
  },
  {
    id: "mj01", img: "mj01.jpg", arcana: "major", rank: "1", name: "魔术师", en: "The Magician", glyph: "🎩",
    upright: { kw: "创造 / 主动 / 资源整合", love: "像他举杖引下天光，想约见面就把话直接说清。石桌上的杯与剑各放其位，约会也值得提前安排细节。左手指地向桌，右手指向光，喜欢就要两头都落到实处。白百合旁立着红玫瑰，心动与承诺凑齐了才开得久。头顶的光环无限延伸，两周之内把这阵热情变成一次行动。", study: "四件法器摆成一排，资料工具和时间也该各归其位。举杖的人只盯一处，攻坚清单一次只推进一项。把最清醒的晨光留给最难的一科，像他把杖尖对准光环。剑在桌上是拆解，遇到难题就切成小段逐个划开。完成一项就在清单打个勾，让专注像光环一样续上。", career: "桌上的杯剑杖币一样不缺，你手里的人脉预算也够开局。他敢把杖举向天空，核心任务此刻就该开口去争。开局阶段亲自对接关键的人，第一声印象最难事后修补。远山与城堡都在视野里，整合资源后定期向众人同步进展。黑袍之下藏不住手势，做没做推动，众人全都看在眼里。" },
    reversed: { kw: "混乱 / 拖延 / 才能内耗", love: "杖举得再高，不落下就只是姿势，承诺要落成一件小事。石桌那柄剑一旦生锈，漂亮话抵不过一次次失约。别只顾递上红玫瑰，白百合般的日常兑现才养得住信任。光环悬在头顶落不到手里，修复期最忌再许新的大话。把指向天地的手收回来，先核对承诺与行动差了几步。", study: "法器摆了一桌等于什么都没练，笔记再精美也要做题。先把桌面清成一张，多余的工具与资料收出视线。手臂酸了就把杖放下，今天只留必须完成的两项。光环断了就没魔力，连续三天做完同一件小事再谈天赋。山再近也要迈步，计划删剩一半才腾得出动手的空。", career: "杯剑杖币全在桌上却摆错了阵，资源好也可能用反方向。汇报的杖举得再花哨，交付不到位迟早被人看穿。把剑收回鞘里，精力挪回最核心的那项产出。开口之前先想清楚能兑现什么，没底气的承诺会反噬自身。远山不动人动，让才华指向一个可验证的结果。" }
  },
  {
    id: "mj02", img: "mj02.jpg", arcana: "major", rank: "2", name: "女祭司", en: "The High Priestess", glyph: "🌙",
    upright: { kw: "直觉 / 静默 / 内在智慧", love: "她垂目读卷，心里那点不对劲先别说服自己忽略。黑柱与白柱之间自有分寸，找个平和的时机把疑问问清。袍角的静气最动人，一次安静的深聊胜过十次热闹约会。幕布上石榴累累，反复想起某人时由你轻轻起个话头。脚边的雾气夜里最浓，深夜的直觉记下来白天再核实。", study: "她独坐柱间不理会外界，长内容正适合一个人慢慢啃。卷轴摊在膝上才读得细，把最难的内容排进独处时段。月冠下的灵感来得轻，冒出的念头随手写进固定的本子。雾气遮不住的水面自静，给学习留出不被打扰的整段时间。黑柱白柱一明一暗，学一段再合卷回想，深浅自然分明。", career: "她眼皮轻阖却什么都听见，会上的沉默先把立场摸清。卷轴不摊开给别人看，判断先写进私人笔记等时机。黑柱旁站得住的人才配发言，信息够了开口自然有分量。幕布后的石榴不急着数，复盘与研究类岗位最能养你。足下水声先于言语，等局势浮出水面再交出方案。" },
    reversed: { kw: "压抑 / 忽视直觉 / 秘密", love: "卷轴抱得太紧就成了隔阂，沉默久了对方只能靠猜。黑白柱立在身前身后，你光站着不动，冰就永远结着。先把最小的一件事说出口，情绪早讲是沟通晚讲成控诉。石榴藏在幕布后数不清，疑心对方时先去核实事实。雾气漫上脚面别装看不见，用一个小小的动作先破冰。", study: "眼睛闭着，念头却比集市还吵，焦虑伪装成了走神。卷轴上的字读不进去时，先把担心的内容逐条写下核对。幕布的石榴图案看花了眼，书页之外的想象先放一放。每天留一段不碰手机的静时，让心像脚边的水面沉下来。两柱之间只容一身，一次只处理一科，专注会慢慢回来。", career: "卷轴攥在手里不发，关键情报攥久了反失了信任。黑柱挡住的传闻，绕不开就直接找当事人谈。白柱下的事实别只留给自己，该同步的进度按时公开。背后幕布上石榴数不全，打听不到的事先别急着下结论。雾气里看不清双柱全貌，猜错的判断往往代价更大。" }
  },
  {
    id: "mj03", img: "mj03.jpg", arcana: "major", rank: "3", name: "皇后", en: "The Empress", glyph: "🌹",
    upright: { kw: "丰盛 / 滋养 / 感官之美", love: "她掌心的金粉落在麦穗上，爱意也该落在每一顿用心的饭里。裙上的石榴一颗颗饱满，共同布置住处最能悄悄升温。溪水绕着麦田走，顺路接送这类小事比隆重表白更养感情。赤脚踩进麦浪也要留神，别只顾照顾对方而亏了自己的享受。田边向日葵开得坦然，被照顾久了要说出谢谢，丰盛才有回响。", study: "整片熟麦在等收割，文科与艺术的内容动手做比反复背更快。蝴蝶绕着她的裙摆，把学习角落布置舒服，状态会被环境养住。溪水边睡莲一朵一朵开，知识做成手账或模型才吸收得牢。她赤脚踩土，身体状态直接连着记忆，别拿熬夜换学习时长。石榴裙沉甸甸都是果实，学到的东西要用出去才算真的丰收。", career: "麦熟到垂穗的时候，项目成果也该大大方方摆出来展示。她张开的两手撒出金粉，对自己人慷慨换得来长久合作。溪流转弯处仍有睡莲，交付做得好看好用会自己引来资源。品牌与生活服务正合这片丰饶，审美本身就是你的竞争力。丰收时别忘了盾石旁的账，回头复盘成本才守得住仓廪。" },
    reversed: { kw: "依赖 / 挥霍 / 创造力阻塞", love: "石榴穿满裙身也压得慌，包办一切的爱会变成双方的负担。溪水漫过田埂就失了规矩，留出空间让对方也来照顾你。盾立在石旁本是防身，别把关心打扮成处处安排。先停下过度的浇灌，看看哪些事本该由他自己承担。付出换不来回应时，把金粉收回来先养自己的园地，怨气自淡。", study: "麦田金黄却懒得下镰，舒适区待久了连书都拿不稳。蝴蝶一引就走神，零食和手机放到另一个房间去。溪边躺卧虽舒服，单次学习先缩到二十分钟再谈强度。笔记描金像石榴裙般华丽，题目一道没做就本末倒置了。完成了就给自己一点小奖励，像麦穗该有的那阵风。", career: "金粉撒得太阔，预算花在排场上产出就跟不上。满园石榴看着热闹，砍掉华而不实的开销，钱投给出活的环节。溪水再美也灌不饱粮仓，账面热闹掩盖不了亏空。盾牌立在田头是提醒，先备好底线再谈体面排场。长期过劳的人像旱了的麦田，主动减负，创造力才重新返青。" }
  },
  {
    id: "mj04", img: "mj04.jpg", arcana: "major", rank: "4", name: "皇帝", en: "The Emperor", glyph: "👑",
    upright: { kw: "秩序 / 权威 / 稳固根基", love: "他坐稳石座手握权杖，承诺按部就班的关系最让人心安。扶手上的羊头盯着日子，纪念日与见家长都提前排进日程。红袍裹着铁甲，可靠之余偶尔主动示弱关系才松得快。掌中的金球是一起攒的家底，共同制定财务计划把日子过成结构。台阶下的向日葵朝着光，偶尔放下主见让对方安排一次。", study: "石座一层层垒得稳，作息与科目也该固定成一张日程表。权杖立定不打晃，规则写在纸上比全靠意志力省力。羊首扶手守着边界，给每科定固定时段，执行率自然抬升。铠甲一片一片编成，错题定期回顾，基础跟着秩序往上走。金球在手里要常掂量，用模拟考验收，秩序才配上反馈。", career: "他端坐高处统观群山，流程权责节点定清，推诿自然减少。权杖指向天空也压住自己，立规矩时把自己先放进去。两座羊头并排而立，兼听各方，规矩落地才没人暗中抵触。铁甲护胸也护团队，带人管预算的位置最宜你坐稳。金球托在左手不握死，交代背景与理由，命令才有来由。" },
    reversed: { kw: "固执 / 控制欲过强 / 僵化", love: "权杖握得太紧就成了指挥棒，处处要报备，对方只剩沉默。羊头扶手再稳也是牢椅，把决定权分一半出去透透气。红袍罩得住全身罩不住人心，先分清哪些是关心哪些是管控。从最小的那件事开始放手，让对方领一次路。台阶一层层走下来，有意见时先听对方把话讲完。", study: "他把权杖攥成唯一解法，死守一种思路，遇到变式就卡住。石座坐久了会凉，老师的答案也允许多问一层为什么。羊头的固执要不得，同一类题刻意换两三种解法去练。铁甲防身也防新东西，把讲解当参考而不是标准。山是背景不是边界，换个路径上山，视野会完全不同。", career: "权杖只朝一个方向挥，一言堂下没人敢说真话。座边羊头各守一边，决策前专门设一个反对意见的环节。红袍威严也隔人，规则定死之前留出可以商量的缝。金球攥紧会硌手，标准写清楚就少做临时改动。石阶要让人走得上来，把反馈通道打开，人心才不会散。" }
  },
  {
    id: "mj05", img: "mj05.jpg", arcana: "major", rank: "5", name: "教皇", en: "The Hierophant", glyph: "📿",
    upright: { kw: "传承 / 指导 / 共同信念", love: "他抬手降福，两旁的修士低头同礼，被祝福的关系更有支撑。适合一起见亲友、参加仪式，谈钱谈未来都不别扭。冠上的三重十字各有分量，价值观的确认比排场更要紧。阶前交叉的金钥匙交给彼此，公开的承诺让感情更稳。热闹之外留一份私下默契，像礼成后并肩走下的那几步。", study: "有长者执杖引路，系统课程从头跟到尾比四处旁听扎实。卡住时开口请教，前人的经验能省下大段摸索。双柱之间的石台供人俯仰，正统解法往往就是最短的那条路。把疑问摆到老师面前，别在原地绕着台阶空转。领了祝福也要自己走路，每章合卷复述一遍才算数。", career: "长者伸手一指，两把金钥匙横在阶前，行业规矩与手艺要同时握住。老同事的经验值得虚心请教，不合理的规矩背后常有缘由。得到提携要拿成果回报，人情与专业得同时立住。两根石柱夹出的位置最考验分寸，把手艺练实，机会来了才接得住。按流程做事容易赢得信任，节点上的汇报别省。" },
    reversed: { kw: "教条 / 质疑 / 另辟蹊径", love: "钥匙交叉搁在阶上，门却没人肯开，形式吵不完，真心没处放。先把两个人想要的生活对齐，再决定要不要向外界解释。旁人的常态不是你们的答案，心里怎么想先说给对方听。冠冕再重也压不住分歧，形式上的争执内部先达成一致。祝福是锦上添花，别拿它当感情的主梁。", study: "结论背得滚熟，讲不出所以然，教条把通透挡在了阶外。对每个结论多问一层依据，能自己推导出来才算掌握。换一种说法把知识讲给外人听，理解的漏洞立刻显形。柱廊之下不止一条路，正统方法走不通就换一条验证。怀疑不是叛逆，把质疑落成一道自己解出的题。", career: "金钥匙锈在了台阶上，前辈的做法照搬到底，环境一变就失了灵。质疑陈规之前先在体系内做出成绩，说服力足得多。新方法先做小样本验证，用结果代替会上无休止的争论。冠冕戴久了容易俯视，换赛道要挑值得学的对象。反抗权威不是目的，别把依赖从一个换成另一个。" }
  },
  {
    id: "mj06", img: "mj06.jpg", arcana: "major", rank: "6", name: "恋人", en: "The Lovers", glyph: "💞",
    upright: { kw: "结合 / 选择 / 价值契合", love: "像牌中相贴的掌心，心动对上节拍，关系自然成立。上方的天使张开双翼却不出手，爱情终究要自己选。左边结果的树与右边燃烧的树都在提醒：选哪边都有代价。白百合与红玫瑰同片生长，好的感情不必改掉自己来成全。若心里已有倾向，别等对方先开口，主动一点这段就活了。", study: "牌下那条穿谷的小溪提醒：有真兴趣引路，再远也走得动。两棵树一边结果一边烧，选方向前先把得失各列一条看清。别在别人的目光里找方向，你心里那顶星冠才是坐标。遇到聊得来的同好或老师，把这份合拍当作学习的加速器。选完就往前走一段再回头评判，反复横跳最耗热情。", career: "合拍的事业伙伴像画里对视的两人，坦率得不用设防。天使张翼俯视而不干预，合作里主角仍是你自己。面临两条路：一条稳如挂果的枝，一条烈如火烧的树，先问本心。价值观一致时，分工可以少谈条款多谈信任。选邀约或合伙前用掌心相贴的感觉检验：对等吗，热吗。" },
    reversed: { kw: "犹豫 / 分裂 / 关系失衡", love: "掌心没有贴上，是有人悄悄收回了手。眼前不是选择难，是你一直在回避选择本身。缠树的蛇在耳边低语，别把一时心动误读成深知。两人志向不同路时，早一点承认，比拖着更不疼。怕选错的心气比选择本身更消耗，做完决定先走一段再说。", study: "想换方向又舍不得沉没成本，僵局本身最耗人。把想要的和不甘心的各写一张清单，那是两回事。光被云挡住不是消失，兴趣只是被太多“应该”盖住了。别再收集所有人的意见，挑一条路先试两周。两周试下来合不合，结论比纠结十天更响亮。", career: "条件体面而每天消耗，这是价值观在报警。两棵树各站一边，你不表态就会被两边当阵地。团队方向分裂时，先评估哪条路你肯真心签字。不合拍的合作别急着缝补，把诉求摊开谈一次。离开不是认输，是把相贴的掌心收回到自己身上。" }
  },
  {
    id: "mj07", img: "mj07.jpg", arcana: "major", rank: "7", name: "战车", en: "The Chariot", glyph: "🏇",
    upright: { kw: "意志 / 凯旋 / 掌控方向", love: "他双手执缰站上金车，认定了就主动推进见面与确定关系。冲刺时回头看一眼同伴的节奏，两人同速才跑得远。两匹狮各有一股劲，一黑一白，缰绳在你手里，方向要提前对齐。星芒悬在头顶亮得笃定，把追求落到确定的时间和地点。遇到阻力先核对目标是否一致，而不是一味加鞭。", study: "双狮腾空的劲头全使在一处，备考攻坚最忌分心。把薄弱科目排在精力最好的时段，像他把缰绳收得稳稳。车轮一圈圈压过草地，每周做一次小结，防止跑快了自己跑偏。星在头顶指方向，方向定准后再加练习量。城墙近在眼前，冲刺期也留一晚睡足觉。", career: "金车碾过草地直奔城门，项目在你的牵引下明显加速。开拓竞标赶进度这类活，气势本身就是优势。一黑一白两兽合力，缰绳不能松，关键节点交给别人复核一次。星芒照着前路，往前赶时别被途中的噪音一次次改道。凯旋也要回头看，把同行的伙伴介绍给众人认识。" },
    reversed: { kw: "失控 / 挫败 / 方向迷失", love: "两兽各朝一边发力，车在原地打转，一方要冲一方要缓。先把速度差摆到明面上谈，方向错了才真正致命。星芒被云遮住时别急着赶路，停下来问清彼此想要什么样的相处。缰绳勒得越紧越容易翻车，追得太急先松两扣。若方向根本相反，及时下车比一路硬拽更省彼此。", study: "双狮拉扯，车轮陷进草里，计划排得太满反而整体趴窝。把周期拆短，每三五天设一个确实够得着的小目标。星芒再亮也照不醒打盹的人，状态差时只保基础题。别学黑狮猛冲白狮撒欢，一曝十寒的战线拖不长久。先定唯一主攻科目，其余明确延后再排。", career: "同时赶几辆车却没人定优先，越急越乱，交付接连失守。先明确唯一的主攻目标再提速，力气才有落点。双狮各奔一方时，把其余任务延后并告知相关的人。遇挫别急着改道，先看清是能力缺口还是路径出了问题。城还在远处，星还在天上，方向理清楚再重新执缰。" }
  },
  {
    id: "mj08", img: "mj08.jpg", arcana: "major", rank: "8", name: "力量", en: "Strength", glyph: "🦁",
    upright: { kw: "勇气 / 柔韧 / 以柔克刚", love: "她跪坐草间双手轻托狮吻，争吵时先接住情绪再讲道理。狮子颈上绕满白玫瑰，温柔的陪伴能驯服最烈的脾气。需求要像托腮的手一样，放得轻也说得清。白袍映着夕光，她毫不畏惧地靠近，自信本身就是吸引力。忍太久会一次爆发，有想法就温和而清楚地讲出来。", study: "她不掰狮口只轻轻一托，难题别硬磕，拆开步骤慢慢磨。玫瑰花冠一圈圈绕上鬃毛，每天留固定时间与难点相处。狮子伏得安稳，是因为她日日都在，少量多次比一时爆发更扛得住。焦虑上头时先做两分钟最简单的部分，像她先把手放上狮吻。草原开阔，一时的瓶颈困不住天天到场的人。", career: "她单膝点地却气场十足，面对强势的同事不必硬碰。狮口在掌中，立场平稳讲清即可，稳住语气就稳住了局面。鬃毛上的玫瑰是众人递来的敬意，把功劳分给协作者，号召力自然上来。夕阳把草原染金，长期承压也要有出口，定期复盘与运动。力量用柔不用猛，你的底气藏在日复一日的稳定里。" },
    reversed: { kw: "自我怀疑 / 失控 / 退缩", love: "手一抖狮口便合上，情绪上头的瞬间，最亲的人最容易被咬。自我怀疑时别反复索要保证，先把注意力放回自己身上。她若起身退开，狮子只会更低吼，冷战从来换不来温顺。先安顿好自己的状态，再去谈关系里的问题。若长期被这段相处消耗，选择离开同样是一种力量。", study: "还没伸手就先怕被咬，难题翻到一半就觉得自己不行。把大目标换成今天确实能做完的一件小事，像她只托住狮吻不碰獠牙。玫瑰冠掉了再编就是，记录连续完成的天数，坚持本身是燃料。一曝十寒等于日日惊动狮子，定个固定的小时段养熟它。畏难时从最有把握的部分入手，难度切成能承受的小块。", career: "被催促时手一松，狮口就合上，一句气话可能抵过全部努力。快要失控时先离开现场十分钟，回来再作回应。狮子认得她的手，底气靠一次次成功交付攒回来。颈间花冠被扯落几朵，高压之下更要稳住语气再开口。别把忍耐当力量，定期找出口复盘，耗空的手托不住任何东西。" }
  },
  {
    id: "mj09", img: "mj09.jpg", arcana: "major", rank: "9", name: "隐士", en: "The Hermit", glyph: "🏮",
    upright: { kw: "内省 / 沉淀 / 求索之道", love: "雪山顶上那盏提灯只照亮一小圈，你也先把自己照明白再谈靠近。兜帽遮住半张脸的时候，急着要答案反而看不清感情的轮廓。独处不是熄灯，是把喧哗调小，听清心里那句真话。想约对方深谈，挑夜里月色那样的安静时刻，别在人群里问。山路蜿蜒漫长，感情的确认不必赶进度，走稳比走快省力。", study: "隐士举灯只为脚下这一步，复习也别贪多，每晚弄透一个小专题。山顶风冷，坐得住的人才能把冷门科目读成自己的强项。长杖点地一步一步算数，把厚书拆成每日的薄页，进度自然可观。星光下的寂静是资源，关掉推送，给自己两段完整的深潜时间。灯要举给值得的人看，定期把笔记讲给同学听，深潜不忘校准方向。", career: "提灯的光晕不大，却足够照亮手里的路，眼下适合做总结与沉淀。退到雪山高处看全局，把手法整理成手册，幕后价值反而更醒目。老者的智慧在杖尖落地有声，找一位前辈深谈，胜过独自摸索半年。夜色里的星星各安其位，不必抢着发言，把你的观察攒成关键一击。下山之前留好归期，露面与沉淀两头都不丢。" },
    reversed: { kw: "孤立 / 封闭 / 过度避世", love: "灯若只照自己，屋里的人会以为你把她关在了山外。沉默拖得越久越像无声的控诉，对方站在山下只能猜测。想独处就直说期限，一句这周需要安静，比整周不回消息体面。月亮再清冷也挂着星星，留一盏灯给想靠近你的人。蜿蜒山路不是绝路，约好每周一次短谈，空间与联结就能并存。", study: "灯举得再高，照的也只是自己画的那个圈，方向早偏了。闭门独坐时最容易把误读当成真知，定期把成果讲出去听反应。长杖该探的是前路不是门槛，别把力气全花在拒绝外界上。每周留一晚下山走走，对照大纲和真题，看看路线有没有走歪。星空辽阔，问一句比闷想一天划算，找老师或同学戳破盲区。", career: "灯光只够一个人取暖的话，团队的需要就永远落在暗处。隐退太久，名单上会慢慢没有你的名字，关键讨论务必到场。杖子扶着人是让你走得稳，不是用来把所有人挡在山门外。常走走下山的路，认领一次协作任务，露面本身就是被考虑的前提。沉淀与同步并不冲突，定个节奏，独处半天再汇报半天。" }
  },
  {
    id: "mj10", img: "mj10.jpg", arcana: "major", rank: "10", name: "命运之轮", en: "Wheel of Fortune", glyph: "☸️",
    upright: { kw: "转机 / 周期 / 顺势而动", love: "巨轮转到这一格，僵了许久的关系忽然有了开口的契机。轮顶的王者端坐不动，等的就是顺势伸手的人，别错过窗口。云层里那只鹰盯准了就俯冲，想回应对方时干脆一点。别让沉默的狮子替你读剧本，把心里的进展当面讲出来。轮子一圈圈转，顺境时多攒共同经历，低谷才有存货可撑。", study: "轮盘转到顺位的时候加量最划算，趁手感好集中攻最弱那科。蛇从轮边滑落提醒人，卡壳的方法该松手了，换一条思路试试。读书的天使不慌不忙，把节奏定成可持续的周期，比突击更管用。符文刻在轮缘转一圈亮一次，错题过完一周再回头清一遍。轮下翻身而下的舞者像一次换位的启示，思路卡住就换个讲法重学。", career: "巨轮启动，此前的积累开始被看见，新项目来了就先进局占位。持剑的斯芬克斯守着机会的入口，把材料备齐再出手，胜算更厚。云端四兽各守一方，别只盯一个风口，把手头两条线都铺好。轮顶的王座不高不矮，位置来了先坐下，细节可以在位上补。转动的轮从不等人准备好，把成功拆成可复用的动作才守得住。" },
    reversed: { kw: "厄运循环 / 失控 / 抗拒变化", love: "轮子倒着转的时候，同一场争吵会一遍遍回到老位置。那蛇顺着轮缘往下滑，旧情绪也在往下带，先停掉熟悉的反应。别学轮下失重的人乱抓，局势打转时先把开场白换一句。鹰在云上看清了才扑，感觉不对时别急着定性，等轮势稳一点再选。刻满字的轮缘转不回昨天，破局先破执念，换回应才有新结果。", study: "轮盘空转不出结果时，多半是路数和考题错位了。再用力也抽不动倒转的轮，先停下复盘，别单纯延长时长。狮子的书是打开的，请别人看看你的笔记，错处一眼就现形。把低潮当成一次体检，对照大纲找出真正脱节的那一环。有角的牛守着田也守着季节，等这段轮势过去，再重新排计划。", career: "错过的这一格要等轮子转满一圈才回来，先把损失认下来。别学那条往下滑的蛇较劲，抗拒已发生的变化只会损耗更重。云上的鹰早已俯冲过一轮，下一个关键节点提前标进日程。斯芬克斯的剑只给有准备的人开路，趁空档把条件补齐。轮缘的字转一圈换一个方向，复盘旧因，霉运才不成循环。" }
  },
  {
    id: "mj11", img: "mj11.jpg", arcana: "major", rank: "11", name: "正义", en: "Justice", glyph: "⚖️",
    upright: { kw: "公正 / 因果 / 理性裁决", love: "天平两端持平的样子，就是关系该有的谈法，把付出摆上明处。直立的剑不偏不倚，有分歧就摆事实讲感受，别用情绪加码。棋盘格一步一算，谁让步多少都记在明账上，才不留暗亏。裙上的蝴蝶轻得像情话，公道之外也要留情分，别赢了账目输了人。两柱之间的位置最稳，约一次对等的长谈，把期待说清楚。", study: "秤盘里的分量骗不了人，复习到位的部分会如实落到分数上。按棋盘格推进，时间留给分值高又没把握的板块。剑锋一样直的细则摆在那里，自测逐条对照，别凭印象估分。脚边的白百合开得不急，薄弱处慢慢补，因果自会结账。端坐石座的人不左顾右盼，按计划走，别拿别人的进度乱自己的秤。", career: "天平与剑各在一手，权衡和决断可以并行，把条款写明白。石柱之间的裁决不徇私，规则明确反而让合作更安心。该争取的像剑一样直说，留好证据链，讲规则比讲情绪有力。红玫瑰摆在明处，报酬别只口头承诺，白纸黑字落定最稳。脑后的光照亮是非，合规类事项适合现在推进，一件件过秤。" },
    reversed: { kw: "失衡 / 偏颇 / 逃避责任", love: "秤盘一边高一边低的时候，这段关系已经在偷偷记账了。总一个人在让步，剑再直也斩不开习惯了的失衡。先停止追加付出，把空出的那格留给对方补位。棋盘上的黑白要轮着走，单方讲理久了，失衡本身就是答案。百合与玫瑰各开各的，把不平衡摊开说一次，再决定往哪边加砝码。", study: "秤被喜好压歪时，弱势科目就被一再挪出了视野。别拿印象当结论，让同学批一次卷子，差距立刻显形。剑该落下时别犹豫，回避的那科正是总分的瓶颈，先啃最小一章。棋盘格不会替你选路，用真题和细则重新校准强弱判断。脚边的花从不挑格子开，各科都留出一格时间，偏见才钻不进来。", career: "天平若斜了，口头承诺和纸面条款就会露出两张脸。签字前把条款逐条过剑，凡承诺都要求落成文字。石座上的裁决也会错，有分歧就按流程申诉，别硬扛。情绪化的对抗像乱摆的秤盘，只会削弱你站得住的位置。棋盘上输了这局还有下一局，留好证据，等规则替你说话。" }
  },
  {
    id: "mj12", img: "mj12.jpg", arcana: "major", rank: "12", name: "倒吊人", en: "The Hanged Man", glyph: "🙃",
    upright: { kw: "换位 / 等待 / 以退为进", love: "倒挂的人不挣扎，头朝下反而看清了世界，争执时先换立场。抱在胸前的双臂是在等，不是在认输，暂停推进不等于放弃。秋叶落一阵才见枝干，关系降温几天，才看得出谁在守着。头后的光环安静发亮，等待期把自己安顿好，回头时才有新面貌。长发垂向大地，把想说的话倒过来讲一遍，用对方的角度重述一次。", study: "系在树上的绳结没有勒疼他，卡住的题放半天再回看，结会自己松。倒着看的世界换了方向，把解题讲给别人听，盲点立刻现形。落叶不是浪费，休息的那几天大脑仍在暗处整理线索。草丘上的根扎得安静，长线科目适合这种慢功夫，日日挂一点。远山在倒挂者眼前反而更清楚，退一步再看书，框架比细节先亮。", career: "让出那只脚的力气，换来的是更稳的悬挂点，短期利益可换位置。抱臂的人在停滞期也没闲着，把证书作品和人脉攒厚。树冠落下的叶子替他计时，等待有期限，转机来了才有落点。光环只给沉得住气的人，让一步之前先算清让掉的是什么。河从山那边绕过来，绕行的这段不算停滞，是在攒承接的面。" },
    reversed: { kw: "僵持 / 无谓牺牲 / 抗拒", love: "绳子若再紧一分就不是修行是消耗，熬干自己换不来感激。一味倒挂着迁就，对方会习惯接受，关系只剩负担感。先分清是自愿还是讨好，再谈这段要不要继续往下挂。落叶铺了一地也不见回应时，把该承担的事分回给对方。光环照不出单方面的牺牲值得，先停下来问还想不想走。", study: "挂太久姿势就僵，死守一种解法越做越乱，效率被空耗拖低。半小时解不出就换路，绳结不是荣誉，别把它当坚持的勋章。秋叶提醒换季，反复无进展时先回看题目条件是否读错。设一个止损点，卡住就求助，方向错了越努力亏得越多。远山不会因为盯着它而挪近，换一种讲法重学，思路才活。", career: "倒挂的姿势撑不起升职，长期加班换不到回报时该重估。别再拿奉献感当工资，把付出换算成成果再去谈条件。树上的绳结解铃还须系铃人，不敢换岗时先练一次换位提案。落叶一季一季地换，僵持的局面也能动一小步试试水温。光环不是熬出来的，是看清之后仍安静的样子，先算清再等。" }
  },
  {
    id: "mj13", img: "mj13.jpg", arcana: "major", rank: "13", name: "死神", en: "Death", glyph: "🦋",
    upright: { kw: "彻底终结 / 蜕变 / 断舍离", love: "黑旗上只绣一朵白花，告别也可以干净，旧模式谢幕不必难看。倒下的王冠说明有些相处方式已经压不住了，与其维持表象，不如把规则重建。白马从旧矛盾上跨过，允许自己难过，但别急着用新人填空位。那个头顶发光的孩子站在原地，空出来的位置先留给自己想清楚。枯树旁草花照开，正式做个了断之后，新的相处才有土可长。", study: "骑士不再修补旧盔甲，笔记体系该删就删，重搭比缝补省力。废墟留在背景里，旧资料归档就好，按最新大纲重列框架。黑旗上的白花是转轨的记号，越早承认走错，损失越小。白马不停在旧战场上，转方向后给新体系两三周的适应期。发光的孩子站在新生一侧，推倒重来难受几天，撑过去就顺了。", career: "老业务像倒地的君王，守残局不如把手艺迁到新方向。骑士离场时盔甲仍然整齐，交接做得体面，口碑会被下家看见。远处的废墟曾是城堡，行业洗牌时先保住可迁移的核心技能。黑与白同在一面旗上，结束和开始可以同时成立，别只看到失去。草地上的小白花不问输赢，转身之后按新方向重新投递一次。" },
    reversed: { kw: "执念 / 迟迟不结 / 抗拒转变", love: "旗子已经立起人却还在回头，反复联络旧人只会把自己拖在原地。倒地的君王不必再被摇醒，翻检旧记录的动作先停下来。枯树不肯落叶才最难熬，先把日常重新填满，答案自会清晰。祈祷的主教留不住白马，不肯结束又不肯修复最消耗双方。孩子头顶的光在提醒，新的阶段已经开始，别把影子留在旧战场。", study: "盔甲都落地了还在翻旧笔记，过时的内容占着新知识的格子。废墟不拆就盖不了新房，按新大纲先列出从没碰的部分。别学躺着的王抓着冠不放，旧方法腾不掉，新容量就进不来。小白花开在翻新过的草地上，从最陌生的一章先补起。蜕变拖得越久越耗，给旧体系办一场安静的告别式。", career: "抗拒转身的代价随时间放大，先小规模试水新领域。骑士的马不会等你想完，环境在变时守着熟岗只会越守越窄。把结束当成一次交接，经验整理成可迁移的清单。废墟上的砖还能砌新墙，旧岗位的技能换个行业重新标价。别怕撕掉头衔，白旗上的花比金冠开得久。" }
  },
  {
    id: "mj14", img: "mj14.jpg", arcana: "major", rank: "14", name: "节制", en: "Temperance", glyph: "⏳",
    upright: { kw: "平衡 / 调和 / 细水长流", love: "两只金杯之间的水线不断不溢，相处的节奏也该这样匀。天使的翅膀一边都不偏，见面与独处都留出位置，感情才养得稳。彩虹出现在雨后不急不躁，稳定的表达比一时的浓烈更让人安心。河从山口流得不快不慢，细水长流的相处里，一起养成一个小习惯。胸前那颗星提醒人，调和的前提是自己先站稳。", study: "水从一个杯子匀到另一个，强弱科目交替着复习，谁也不被晾着。天使不急不慢地倾倒，把任务拆成每日的均量，比突击贴合记忆。彩虹要等水汽和阳光配比恰好，学到留一点余量再停手。山间的路一段一段走，长线计划按周验收，别一次赌结果。脚边的溪不喧哗，安静的积累到某天会忽然成形。", career: "跨方的诉求像两杯之水，被你调和进同一个方案，推进不必靠施压。双翼展开覆盖两端，协调类工作正适合现在，把人调和好就是价值。彩虹的每种颜色都保留，资源分配留一成机动，突发才砸不出窟窿。河绕着山走而不改方向，目标坚定，手段可以柔软。星冠戴在额头，节制的人才被信任，节奏稳的团队会点你的名。" },
    reversed: { kw: "失衡 / 极端 / 缺乏耐心", love: "水洒出杯外时，天平就悄悄歪了，忽冷忽热最伤人心。翅膀只顾一边飞，忙碌时彻底失联，对方只能在猜测里打转。彩虹勉强拼出来也会很快散，稳定的联系频率比偶尔的浓烈养感情。断流的河床露着石头，过度付出与突然冷漠之间，先处理自己的失衡。天使的脚步停在溪边，把可用的时间提前讲明，再谈靠近。", study: "一杯倒得太满一杯空着，一天学到虚脱再歇好几天，进度在两极间晃。星冠再亮也照不了夜路，把每天的下限定得很低，少量不断胜过间歇拼命。水线断了就没有彩虹，极端用功之后必有倦怠，休息要写进计划。翅膀失衡飞不高，学累了换内容而不是硬撑。山口的水讲究细水长流，把长期目标折回每日的均量。", career: "水从杯沿泼出去，预算一次押光，中间没有缓冲，小事故就演变成危机。彩虹强求不来，急于证明自己时最容易失度，先验收完上一阶段。单翼撑不起身体，把目标拆成可交付的小步，宁可慢一点也留回旋。河滩上的石头等着被踩稳，补上流程里的缺口再谈提速。节制逆过来是提醒，资源调配失度的地方，先减再加。" }
  },
  {
    id: "mj15", img: "mj15.jpg", arcana: "major", rank: "15", name: "恶魔", en: "The Devil", glyph: "😈",
    upright: { kw: "欲望 / 束缚 / 物质诱惑", love: "倒悬的火把照不亮路，占有欲越旺，人心越看不清。石台上的影子压住两个小天使，查手机与限定社交都是这种影子。脖子上的链子看着粗，其实多半没扣死，先把条件摊开谈一次。分清吸引还是依赖，占有感强烈并不等于在乎得深。尾巴扫过脚背的痒，像一时冲动的亲密，激情退去要看还剩什么。", study: "大恶魔举着倒火把，娱乐的快感把长时段专注照得粉碎。小天使被链子牵着走，消息一响就放下笔，自律一点点被蚕食。石台刻着裂缝，逃避的根源常是怕做不好，不是真的懒。黑背景里看不见出口，先把手机放到另一个房间，用环境代替意志力。链环一节一节扣上，也一节一节能解开，从最小的一节开始。", career: "高薪像石台上那团火，好看，但倒着举的火把照不清前程。两个小人被同一条链牵着，竞业与考核条款要逐字看完再签字。蝙蝠翅膀罩住头顶，若一份工让你不敢想退路，先悄悄攒自己的筹码。恶魔蹲踞不动却处处都在，含糊的承诺全部落到纸面再评估。锁链松紧只有自己知道，待遇之外先算清你要付出的自由。" },
    reversed: { kw: "觉醒 / 解脱 / 直面阴影", love: "链子松开的咔哒声很小，小到有人不敢信自己已经自由。火把正过来能照路，当初为何愿意被捆住，看清才不至于换一处再戴。小天使背上的翅膀本来就在，只是低头太久忘了能飞。边界温和地守住，好的关系经得起你说不。挣脱之后别急着找下一个台子，先在空中站一会儿。", study: "锁扣松了才发现根本没锁死，拖延的恐惧大半是自己加的。火把倒转回来，看清逃避的触发点，压力立刻松了一半。从最容易的一项动手，用完成感推动下一项，比自责有效。石台上的裂缝不再吓人，把大任务拆成能跨过去的小格。摆脱干扰之后要有替代安排，不然旧习惯会趁夜色悄悄回流。", career: "脚链脱落是信号，不合理的制度已经开始显形，你不再装作看不见。走之前把退路和交接安排好，解脱要建立在清醒之上。翅膀重新展开前，先复盘当初为何接受那份条件。恶魔的影子还在台上，但光照进了黑底，限制条款一条条可以谈判。挣脱一处锁链不等于自由，换个环境别重复同样的处境。" }
  },
  {
    id: "mj16", img: "mj16.jpg", arcana: "major", rank: "16", name: "高塔", en: "The Tower", glyph: "🌋",
    upright: { kw: "突变 / 崩塌 / 真相毕露", love: "闪电劈下来的那一刻，藏了很久的裂缝终于被照亮。烧红的窗映出积压的矛盾，此刻的痛是真相到位的代价。王冠飞离塔顶，先放下身份与输赢，情绪最高点不作重大决定。坠落的人护着头，你也先照顾安全与感受，结论晚几天再下也不迟。废墟底下能看清哪些砖本就不实，重建不必照原样再垒一遍。", study: "塔身裂开的那道缝，正是死记硬背守不住的题。火从窗口冒出来，意外的失分暴露的是地基漏洞，先回到定义。碎石坠落有先后，错题按漏洞大小排优先级，重建理解比刷新题急。王冠被击飞，名次和侥幸都让位给真实水平，这未尝不是好事。趁崩塌后的清醒，把那些取巧的方法一并拆掉。", career: "架构重组像那道闪电，虚楼不塌才轮不到你站稳。火舌卷着王冠飞走，头衔最不可靠的时候，先保核心业务与个人口碑。坠落的两人姿势不同，乱局里不推责也不慌报，冷静最值钱。塔基的岩石还在，盘点真正属于自己的手艺与信任。重建的窗口就在尘埃落定后，把复盘落成流程，别靠人情补位。" },
    reversed: { kw: "余震 / 幸免 / 抗拒真相", love: "雷声过去了余震还在，谁都不提的裂缝不算愈合。焦黑的窗洞要修补，挑都平静的时刻把当时的感受讲完。被甩落的王冠没人捡了，余震期先别急着许重大的承诺。烟散一些才看得清，当初哪些隐瞒让塔摇得那么快。地基重新砌稳之前，两个人轮流扶一段墙，比指责省力。", study: "这次侥幸没塌，不代表承重没有问题，漏洞仍在暗处。裂开的塔砖要一块块换，把暴露的短板列成清单按优先级补。窗口里的火熄了，别只庆幸跑得快，方法不改下次还会塌。碎石扫干净才能重新砌，先回到基础定义，再碰新题。岩基受潮的部分最该查，考场上最容易慌的环节先演练几遍。", career: "危机缓释期，损失止住了，流程上的漏洞是这次最贵的收获。倾斜的塔身还能扶正，把复盘结论落成可执行的制度。抗拒承认问题只会延长假安全，尽早公开信息才能真正止损。坠落的人被大地接住，先安顿团队情绪，再谈责任归属。重建从塔基开始，用人情替流程补位的日子到此为止。" }
  },
  {
    id: "mj17", img: "mj17.jpg", arcana: "major", rank: "17", name: "星星", en: "The Star", glyph: "⭐",
    upright: { kw: "希望 / 灵感 / 疗愈宁静", love: "头顶的大星倒映进池里，水面终于静下来。壶口缓缓倒水，像疗愈你的人被你温柔对待。不必给关系写死每一步剧本，让愿想自己生长。白鹤在岸边安静站着，等待不等于被动空耗。在星光下聊聊各自的愿想，方向一致就多靠近。", study: "八芒星照得清澈，脑子里的乱麻也理顺了。一柄壶往池里倒水，另一柄往土地浇灌，学习要兼顾输入和输出。把那个遥远的目标拆成每天能做的小步骤，星光才照得进日子。灵感足的时段先做写作与创作类的功课，背诵留到后面。赤脚探探水的温度，合不合适自己试了才知道。", career: "星光落在两只金壶上，愿景与手艺要分两处落地。把作品集像果树那样一颗颗整理出来，愿想才有凭据。流入池中的水不急不缓，长线规划也按这个节奏推进。白鹤守在浅滩等鱼，耐心与准备一样都不能少。公开你选定的方向，像大星挂在天顶，让人看得见。" },
    reversed: { kw: "迷失 / 信心受挫 / 灵感枯竭", love: "大星被云遮住时，别以为光已经熄灭。壶里的水停倒了，池面与土地一起发干。别替对方预设最坏的结局，先把自己的门推开一条缝。先给自己倒一小杯水，信心从最小的确定感攒起。白鹤挪去别处不是离开，你也不必守在原地空等。", study: "池里的星影晃了，先稳住呼吸再定目标。壶口倒扣着出不来水，灵感枯了硬挤也没有用。回到最基础的那页内容找回手感，方向是走着才清楚的。别只盯着排名，把今天真正学会的一条写下来。果树结果是一颗一颗来的，每天的小输入胜过熬夜的雄心。", career: "星光暗下来的时候，先别急着换赛道，先补自己的电。两柄壶都停了水，池子和土地会同时干裂。把目标缩到本季度能验证的一件事，让小小的胜仗重新点亮前路。别拿别人的进度衡量自己的路，白鹤有它自己的迁徙季节。先把手边有把握的小事做完，愿景才会重新升起来。" }
  },
  {
    id: "mj18", img: "mj18.jpg", arcana: "major", rank: "18", name: "月亮", en: "The Moon", glyph: "🌕",
    upright: { kw: "幻象 / 不安 / 深层潜意识", love: "月亮闭着眼，照不全整条小路，含糊期最易靠猜。对方那句没头没尾的话，后半段多半是你自己补的恐惧。别让犬与狼在夜里对叫，挑平静的时刻直接问清。把担心的事逐条写在纸上，想象在核实之后会缩小。小路从双塔之间穿过，一步一步走才不会撞墙。", study: "雾气没散，半懂的概念最容易画蛇添足。螯虾从池底爬上来，藏着的漏洞迟早露头。把含糊处先标出来，回到定义和例题重打地基。双塔挡住半边天，夜里昏沉时别硬啃难题。月亮只露半张脸，知识也要查清另一半再做题。", career: "双塔之间没有月光，传闻与半截消息飞得最欢。事实成形之前只做能核实的事，往来一律留下书面记录。犬与狼同时仰头，此时表态容易被当成替谁站队。螯虾举着双钳，敏感事务上离抢功的人远一点。小路弯弯绕绕本就适合慢行，等月亮升起再判断不迟。" },
    reversed: { kw: "拨云见日 / 恐惧消散 / 澄清", love: "月亮睁开眼，你以为吓人的路其实平坦。把最担心的那件事讲出口，想象里的严重性当场缩水。疑云散了，信任仍要一点点重建，别拿翻旧账当确认。犬与狼停下对叫，各守小路两侧，两种声音不必分出胜负。残余的不安若还在，就约定一个定期核对感受的方式。", study: "月光落进池里，原先打结的知识排到了岸边。把剩下的疑点列成条目逐个攻破，踏实感会持续回来。螯虾退回水中，你补掉的基础漏洞已经悄悄合拢。这段难得的清醒，正适合专攻最薄弱的那一块。双塔之间的小路如今看清了，照着它走完这个考期。", career: "雾散月升，原以为的针对其实另有缘由。趁沟通顺当把顾虑谈开，含糊的规则一次问明白。犬与狼各自回岗，不必再疑心身边的同事。余波未平之前少下重注，等结论正式落地再推进。螯虾离了岸，浮出水面的隐情是这次最贵的收获。" }
  },
  {
    id: "mj19", img: "mj19.jpg", arcana: "major", rank: "19", name: "太阳", en: "The Sun", glyph: "☀️",
    upright: { kw: "成功 / 喜悦 / 活力全开", love: "太阳在头顶笑着，这段关系也适合放到亮处。孩子张开双臂伏在马背上，欢喜就该坦率表达。把对方大方介绍给朋友，坦荡会让这份明亮维持更久。顺境里留一次真诚深谈，欢笑之外还需要彼此理解。墙外的向日葵齐齐朝着同一边，两人步调一致的时候要多同行。", study: "太阳照得通透，难点读几遍就顺了。孩子骑在白马背上不怕高，敢把目标定得更远。趁精力旺盛集中解决难题，同时守住睡眠这条底线。把这段顺利的方法与作息记录下来，低谷时照着恢复。草地边的小白花开得也认真，别只盯着最亮的那轮日头。", career: "太阳把孩子举高，成果被放到台面上展示。把功劳分给团队，顺境里攒下的口碑是日后的助力。墙外一排向日葵朝着光，个人的亮眼来自整队的托举。公开亮相与分享都放在这段做，被看见本身就是下一份机会。热闹里留好备份与账目，别让细小隐患藏在强光背后。" },
    reversed: { kw: "延迟 / 虚旺 / 快乐打折", love: "云从太阳前走过，热度暂时降了一层，不必当结局。谁都不肯先开口，白马停在草地上不往前。一句温和的话就能让温度回来大半，别让面子挡路。若总觉得快乐不够，先查有没有需求一直没说出口。向日葵在日头藏起时仍朝着墙，给感情一点等待的耐心。", study: "日光忽隐忽现，状态时断时续的时候最忌赌感觉。考得一次好便松劲，漏洞会在下次题目里冒头。把最意外的几道错题挑出来补根基，那里才藏着真分数。把白衫上的太阳徽记放回日程表，用固定流程推进。别靠当天的情绪决定学不学，阴天也要把小步走完。", career: "太阳晚升了半步，批复与反馈都比预想的慢。趁等待期把成本与细节复核一遍，稳一些反而落地更快。表面的热闹不算终点，没走完的流程一项项补齐。马背上的孩子收了笑，团队疲惫时别硬撑排场。砖墙还立着，把打地基的活逐项做完，日头会重新升高。" }
  },
  {
    id: "mj20", img: "mj20.jpg", arcana: "major", rank: "20", name: "审判", en: "Judgement", glyph: "📯",
    upright: { kw: "觉醒 / 召唤 / 复盘新生", love: "号角吹响，沉睡许久的旧结被重新唤醒。从棺木里起身的人手按胸口，像准备好重谈一次的你们。回应召唤不等于抹掉过去，先讲清准备改变的具体承诺。把旧问题正式重谈一次，结论说清而不是含糊翻篇。光从云端落到湖边，看清了再开口，说的话才实在。", study: "号角是总攻的号令，错题与旧卷在这一阶段最值钱。把常错类型整理成一页清册，考前逐项过关。从木棺里坐起的人先收拾旧错，回看才能跃升。金光劈开云层压下来，越接近终考，复盘越有分量。反复出错的题别放它继续睡着，它们决定你的涨幅。", career: "号角响起，考核结论即将揭晓，积累会被正式结算。结果落地前把材料与数据整理清楚，正式沟通时有凭有据。若光指向新方向，先评估承接条件再动，转型要备好落地的一步。离开木棺的人朝光舒展身体，想换赛道先承认过去的账。旗帜在云端翻动，新阶段的规矩会随结果一起公布。" },
    reversed: { kw: "自我怀疑 / 回避审视 / 犹豫", love: "号角举在嘴边却不响，旧账每次争执都被翻出。棺中人躺着不肯起身，谈不出结论只会越谈越乏。要么正式谈一次给出结论，要么决定放下就从此不再翻。别把自我审判堆到对方身上，先把旧账与事实分开放。光被云层挡着，召唤没有消失，只在等你掀开棺盖。", study: "不敢回看失败的卷子，同一个坑就会再埋你一次。把复盘当成普通作业安排，只找原因，不给智商下判词。一直回避的那一科正是提分的关键处。从最简单的一份旧卷开始，起身也需要一点力气。号角不响就永远卡在云端，回避审视的人等不到跃升。", career: "述职被你一拖再拖，成果因缺少呈现而被低估。躺着的人看不见外面的光，躲开评审也躲开了机会。提前把材料和数据整理清楚，主动请求一次反馈。错过一轮考核不算终局，补齐材料下一轮再呈上去。号角被云层闷住，犹豫才是这场考核里最贵的成本。" }
  },
  {
    id: "mj21", img: "mj21.jpg", arcana: "major", rank: "21", name: "世界", en: "The World", glyph: "🌍",
    upright: { kw: "圆满 / 达成 / 新的视野", love: "少女在花环中央起舞，关系走到了圆满的节点。见家长、订婚或共同定居，值得认真庆祝一次，让圆满留下凭据。四方灵兽各守一角，像生活的四根柱子，理顺了就同路。抵达之后仍需共同维护，把下一段愿望一起写进蓝图。花环合拢无缺，走过的路终于可以从头回望。", study: "两柄杖在怀中交叉，标记一个阶段的收官落定。先彻底休整一场，再带着更大的视野选下一站。把已有积累整理成作品集或申请材料，鹰会带你飞更高。四方生灵各归其位，把听说读写的本领排成体系。花环没有缺口，收官也别留潦草的尾巴。", career: "项目全链路收尾干净，花环里的舞步别人看得见。把经验沉淀成方法并公开分享，更大的舞台由这些展示牵来。结项归档做细致，完整感会转化成下次的信任与推荐。狮子与牛守着外围，前方的名声需要后方的流程接住。天使在角落注视，新的合作周期已经在你身后发芽。" },
    reversed: { kw: "未竟 / 差一步 / 迟迟不收官", love: "花环缺了一角未合拢，承诺总差最后一步。婚期、同居或见家长一推再推，等待久了热情会磨薄。推迟要附上真实原因，再给一个明确的时间点。执杖的少女迈不出舞步，不安全感不说清就成了借口。四方灵兽还在原位等着，悬而未决会拖住所有人的日程。", study: "前面基础扎实，最后一段却潦草，失分集中在细节与格式。花环没合拢，终检值得单独安排一轮。把格式、步骤与细节照清单逐项核对。没补完的尾巴也要收尾，舞还没跳完就不能谢幕。别急着赶新周期，收尾质量不过关，旧问题会跟着重来。", career: "结项材料与交接文档没做完，成果就难真正落地。列出未闭环的事项逐项清账，最后一环最贵也最值钱。花环有缺口，项目停在半空，别急着拥抱新机会。若因自满止步，新的周期会拖着旧尾巴一起重来。鹰已在环外展翅，先把这一环扣上再谈更大的舞台。" }
  },
  // ===== 权杖 Wands (wa01 - wa14) =====
  {
    id: "wa01", img: "wa01.jpg", arcana: "wands", rank: "A", name: "权杖王牌", en: "Ace of Wands", glyph: "🔥",
    upright: { kw: "灵感火花 / 激情 / 新起点", love: "权杖抽出新叶，心动也是有形状的信号。手从云里伸出来，把邀约说出口，约个具体的日子。山下的河刚开始流，初识的阶段天然就快。日光落在树皮上，刚认识的热乎劲儿值得大方回应。树根先抓紧大地再抽芽，快也要留一层底子。", study: "杖头忽然抽芽，对一门学科的钻研欲到了。趁高峰期把入门框架搭完，窗口只开几个星期。每天留固定时段碰它，把理解存成笔记。云中之手递来的柴火，接住后要转成规律的任务。新叶是一片片长的，把兴趣过成习惯才算落地。", career: "新杖到手就扎了根，灵感与机会同时出现。各方还在观望，先启动的人容易拿到主导权。把第一步拆成本周能交付的成果，让热情变成看得见的进度。计划别只在脑中推演，先迈出一步再边走边调。河源很浅但方向清楚，小成果也有自己的冲劲。" },
    reversed: { kw: "熄火 / 冲动 / 时机未到", love: "杖上的叶子打了蔫，热情来得快去得也快。火苗被风吹凉时，先减少联系的密度再谈别的。给彼此两三周冷静期，看看想念是习惯还是真心。手还攥得紧，根却没抓住土，急着定性反而不稳。看清是一时新鲜还是长久心动，再决定松不松手。", study: "抽出的嫩芽枯了，三分钟热度烧完只剩空壳。把目标缩到不可能失败的一步，靠规律重新点火。熄火期硬加时长只会更厌学，先守住能完成的量。抓过柴火的手暂时收回，新窗口要在一两周规律之后才出现。根还没抓紧土，先做底线任务再谈扩张。", career: "杖身锯口还新，芽没冒出就急着宣布开局。会上立下的军令状声音很大，方案却迟迟不落地。先验证方案里最没把握的一环，手的力道不如根的稳固。人手与预算未到位就再等等，晚出发好过中途散伙。河水藏在草后没断流，时机未到不等于源头枯竭。" }
  },
  {
    id: "wa02", img: "wa02.jpg", arcana: "wands", rank: "2", name: "权杖二", en: "Two of Wands", glyph: "🌐",
    upright: { kw: "规划 / 远见 / 掌握全局", love: "手里的地球仪像两人的未来，值得摊开共商。先各写一份蓝图再对照，差异处藏着没说出口的顾虑。去哪座城市发展，何时见家长，把日程写进地图。海上那两叶帆还在远处，定好下次核对的时间再推进。站上城头望得远是好事，脚步也要落回石阶。", study: "他把目光越过海面，目标也该定得远一些。考研还是出国，路线定了就认真走完一两个月再调。给每个阶段设一个可检验的小目标，像在海图上标港口。地球仪在手里，脚却站在城墙上，规划要兼顾高度与立足点。石狮安静守着城角，手头的资料与工具是后方支撑。", career: "手头业务上了轨道，眼前的海就是新版图。扩张前先确认后方团队接得住，别让自己成为唯一支撑。出发前把交接名单与培养计划列清楚，后方稳了前方才敢走远。远处帆影还小，别用单笔数字论一条赛道的成败。手里的地球仪要转着核对，落子的位置靠数据说话。" },
    reversed: { kw: "犹豫 / 固守 / 畏于未知", love: "地球仪在手里转不动，一到承诺话题就绕开。回避的背后有具体的顾虑，讲清比沉默更能松动僵局。脚下的城墙很稳，可海的那一边并不是悬崖。可以先试一次不谈承诺的共同计划，比如短途出行。石狮守着原地多年，别让关系也站成一座雕像。", study: "今天换资料明天改方法，像手里的地球仪转个不停却落不了地。先给每个方案定一个考验期，再谈路线。哪怕选次优的路完整走完一轮，也胜过站在城头比较。两根杖已经插在城头，别再拔起来换个方向插。对远帆的畏惧多半是想象，走一轮就知道海没那么宽。", career: "熟悉的业务顺手，新项目却本能地想摇头。试着认领一次小规模的拓展，先迈小步再谈版图。把熟悉业务做成可复制的流程，腾出人手再接下一单。错失的机会常在半一年内以类似面目重新出现。城头的人望着地球仪不上船，蓝图就只是球体。" }
  },
  {
    id: "wa03", img: "wa03.jpg", arcana: "wands", rank: "3", name: "权杖三", en: "Three of Wands", glyph: "⛵",
    upright: { kw: "拓展 / 初果 / 静待远航", love: "海上归帆渐近，像陆续传来的答案。红披风被风鼓起，关系进入升温与展望的阶段。站在崖上望得远，双方也开始把彼此写进以后。展望期容易理想化对方，把可能出现的分歧早点摆开。感情能否落地，看你们第一次共同处理现实问题的样子。", study: "崖上的人望着远帆，课内扎实之后该把眼光放出去。主动争取交换与深造的机会，让所学往外用。向外的机会反馈周期长，投递后一两个月没动静属正常。三柄杖稳稳插在岸边，手里的功课别松。就算帆影一时不来，流进海的河也从未停过。", career: "出海的船带回第一笔订单，也带回市场的口信。首批回报常带试探性，别按单笔数字判断整条赛道。趁势追加投入并盯紧交付，把首批客户做成长期伙伴。把回款周期与沟通成本算进预算，扩张的节奏才踩得稳。崖上的三柄杖像走过的三步，站稳这里并非侥幸。" },
    reversed: { kw: "受阻 / 短视 / 回报延迟", love: "帆影在海平线迟迟不见，约好的计划一再推迟。坐下来核对双方的时间表，比站在崖边空等有用。等待消耗的是当下的人，方向不一致再守也无益。对方一再推迟又给不出解释，答案写在行动里。浪一次次拍打崖脚，披风凉了，先下山添件衣。", study: "船迟迟不回，旧复习路线与考纲早已错位。回头审视整条备考路线，先校准方向再重新发力。停滞期忌把焦虑换成加量，给每个复习环节定一个核验点。调整见效要到下一轮模考，别在半途又一次改道。三柄杖还立在岸边，攒下的底子不会作废。", career: "谈妥的合作迟迟不签，远方市场不按预期回应。把受阻环节逐条复盘，分清是渠道问题还是需求错配。回款与订单延迟时设一条止损线，再等一轮而不是加倍投入。调整打法之后再出海，比硬撑在崖上更聪明。河水仍在入海，只是出发的船要先清点一遍。" }
  },
  {
    id: "wa04", img: "wa04.jpg", arcana: "wands", rank: "4", name: "权杖四", en: "Four of Wands", glyph: "🏡",
    upright: { kw: "里程碑 / 安定 / 欢庆时刻", love: "把四根扎地的杖搭成花门，两人的花束同时举过头顶，你们的喜事值得郑重开场。白裙与金衣在门下相视一笑，谈婚期前先确认双方都愿意走进同一扇门。山岗上的城堡挂着旗，家不是终点而是共同守住的据点，进度慢些也稳。篱边蔷薇与百合都开了，筹备庆典时把彼此的付出逐一说出口道谢。热闹散场的土路要一起走，婚礼之后谁做饭谁记账，提前分工才安稳。", study: "四根杖搭稳的门楼，是这轮复习收官的牌坊，先给自己一个像样的奖励。花束举得越高，越提醒你把这段规律作息的功劳记进笔记首页。村舍的窗透出安定，把高效周期的时间表原样抄下来，日后照搬。庆典上两人交换笑容，找个人互相复述本轮收获，说出口的才算真会。门外的土路还长，归零之后从错题最薄的那一段重新起步。", career: "杖门落成如同项目验收，团队在门下举杯，功劳要当场分给每位伙伴。高处的旗是里程碑，把这次的流程写成模板，留给下一队人少走弯路。花环缠住的横梁承得住重量，庆功时答应的资源记得落成文字。村舍炊烟平常却珍贵，验收过后的日常运维排班，提前排到人头上。百合开在门脚，庆典留档与数据，晋升答辩时是最硬的凭据。" },
    reversed: { kw: "根基不稳 / 未安 / 庆祝落空", love: "杖门歪了一根，喜帖便不好发出去，婚期与房款谈不拢时先缓一缓。举花的手垂了下来，别用排场掩盖分歧，把卡住的那件事拆开细谈。城堡还远在山顶，两家对家的想象不同，先统一自己人再坐下来议事。藤蔓枯了几条，庆典落空不是坏事，正好检查地基哪块砖是空的。土路扬起尘土，共识往往在一次共同处理麻烦之后形成，别光靠想。", study: "门楼立不稳是因为柱脚埋得浅，综合卷一测就露出被跳过的薄弱章。花束散了架，赶进度的计划同样松散，放慢半拍回补基础更划算。村道尽头没有炊烟，庆功延后别赌气，列出漏洞按提分快慢排序。蔷薇扎手，先补性价比最高的那块短板，其余的等门稳了再修。歪门下站久了会习惯性焦虑，把目标缩到每天一页真题为止。", career: "四根杖有一根裂了缝，交付看似完成，尾款与遗留问题还挂着。花环遮不住榫头松动，把复盘排在庆功前面，先堵漏再开席。山顶旗飘得高，宣传成果前先把责任人和整改时限写清楚。门洞空空穿堂风凉，口头共识留不住人，落成新版流程才算堵住。土路被踩得凌乱，隐患没人提不等于消失，验收单要逐项签字。" }
  },
  {
    id: "wa05", img: "wa05.jpg", arcana: "wands", rank: "5", name: "权杖五", en: "Five of Wands", glyph: "⚔️",
    upright: { kw: "竞争 / 磨合 / 观点交锋", love: "五根杖在半空交叉却不伤人，小吵小闹是磨合，把在意的点说透。蓝衣与红衣各守一边，生活习惯冲突时轮流举证，别抢着挥杖。河滩草地被踩出脚印，吵完当天用一句话确认结论，防止旧仗重打。少年们眼神没有火气，争执时盯着问题本身，别翻对方的旧账。远处城楼安静站着，吵完并肩走一段，边界在交锋里越磨越清晰。", study: "场中杖影交错如比试，把同窗当镜子而非对手，切磋最能暴露盲点。五人各握一根杖，小组研讨时每人先讲一条论据，不许插话。脚下百合开得从容，比拼进度再快也留一页独立自测的安静。谁也没真用力挥杖，课堂争辩对事不对人，输赢之外记下收获。河对岸的塔尖是目标，被带乱节奏时回到自己的错题本上扎营。", career: "五杖同场比拼，多人争一个机会时，把自己那根杖握得最稳。灰褐与草绿各有阵营，方案擂台先亮数据，嗓门大不等于杖法准。少年们脚底站稳马步，上场前把最强一版方案练到熟极而流。草地花开在战场脚边，竞争间隙主动帮对手递一次水，口碑是长线。河水平静映着混战，赛后复盘对方方案里可学的部分，输也输一层皮。" },
    reversed: { kw: "内耗 / 回避 / 无谓之争", love: "杖举久了都累，为吵而吵的循环里，先叫停的人是给理性让路。交叉的杖缠成死结，同一件旧事第三次拌嘴时，停下来找源头。没人真想把杖挥下去，回避争执的一方先开口，哪怕只说一句软话。河滩的风把火气吹散，约一个暂停手势，冷却半小时必须回场谈完。少年松开杖后退半步，体面地休战，输赢让位于两个人的舒坦。", study: "五根杖打成一团乱麻，恶性内卷耗掉深夜，效率比名次先垮。怕交锋就退到场边，可模拟考照样摆在桌上，硬着头皮上。缠斗的少年忘了为何而举杖，比较之前先问自己要什么分数。脚下玫瑰被踩进泥，熬夜堆时长伤身体，用每日进步替代盯人。河岸宽阔足够五人散开，退出混战后拿自己的历史成绩当标尺。", career: "杖杖相缠谁也挥不出去，内斗的团队先停下来谈分工。混战耗的是同一片草地，争功甩锅之外，正经活没人认领。远处城镇需要合力建设，找一个外部压力，一致对外最快解结。松开杖柄试握手，把一项跨组任务的目标与双方考核绑在一起。河水分流仍归一处，谈规则时把利益摆桌面，和气才不是忍气。" }
  },
  {
    id: "wa06", img: "wa06.jpg", arcana: "wands", rank: "6", name: "权杖六", en: "Six of Wands", glyph: "🏆",
    upright: { kw: "凯旋 / 认可 / 众望所归", love: "白马佩着花环缓行，恋情公开收获满街好评，甜也记得回到日常。桂冠戴在头上，掌声之外问一句身边人心里是否真的舒坦。五名随行仰头注视，享受羡慕时别为迎合期待而表演甜蜜。高举的杖是承诺的旗，凯旋之后把功劳分给陪你走过低谷的人。棕榈夹道的大路宽敞，被祝福的关系更要守住两个人的私下节奏。", study: "头名骑白马过街，表扬到手时把这次奏效的时间表原样留两周。桂冠沉，名次更沉，卸下来总结哪几科因祸得福地补牢了。随行五人各持一杖，同学来请教时讲题，讲得清才是真会。马胸前花环鲜艳，晒成绩的高光页翻过去，错题本继续每天过。大道尽头掌声会停，趁士气正盛把下阶段目标写在计划首页。", career: "杖举得最高，晋升名单念到你的名字，领奖台先谢团队伙伴。白马路过之处人群随行，士气正盛时提资源申请最容易批。桂冠是别人给的，交付标准要自己守住，别让凯旋变成新起点的高压线。随员仰头看你怎么走，此后一举一动都被当常态要求，提前定目标。棕榈树影落在凯旋路上，把项目数据归档，下次竞选有实打实的凭据。" },
    reversed: { kw: "自负 / 落选 / 期待落空", love: "马背上的人只顾挥杖，忘了身后随行早已散开，面子赢了里子空。桂冠歪了先扶正心态，落选的祝福没到，别拿冷淡试探对方。花环遮不住马的疲惫，热恋形象经营久了，把真实需要说出口。仰望的人也会低头离开，期待落空时只提一条具体的不满。凯旋街空无一人，坐下来谈一次走心话，比十张合照管用。", study: "名单上没有你的名字，桂冠没戴上，先把那张失分卷子拆开看。白马掉头走离人群，气馁时别把热爱一起丢掉，名次只是快照。随行散了队，漏洞却露了出来，按错题类型补最集中的那一块。高举的杖垂下来，正好腾出手做复盘，把没做完的题单统计。掌声停后的路要自己走，两周基础计划比一场眼泪更长。", career: "捧杀如烈日照桂冠，夸奖声里藏审视，得意时少说多做。马失前蹄在人群前，落选已成定局，改去请教评价标准。随行杖阵缺了一角，团队功劳独吞一次，下次就没人同行。花环枯萎提示筹备不足，把差距拆成半年可补的项再竞选。大道变窄，侧身让一让，口碑比头衔耐用。" }
  },
  {
    id: "wa07", img: "wa07.jpg", arcana: "wands", rank: "7", name: "权杖七", en: "Seven of Wands", glyph: "🛡️",
    upright: { kw: "坚守 / 捍卫 / 以少敌多", love: "他手里只握一柄杖，却站得比六柄插地的都稳。感情被亲友议论时，先分清哪些声音值得答。守立场不必拔高嗓门，把两个人的日子过成看得见的样子。山坡下的溪水绕着走，反对的声音也会绕着散。你守的不是面子，是这段关系的边界与节奏。", study: "六柄插地的杖像六个质疑声，你手里那柄才作数。模考起伏时守住自己的计划，比追着别人改更有效。站得高的人先看见山路，别被脚下的碎石绊住眼。把质疑写成清单，一柄一柄处理，别一次全揽进怀里。山顶的向日葵朝着光，你的方向也该朝着目标。", career: "一人立于岗顶，六柄插地像六个来挑战的位置。优势在你手里，守成比抢攻更需要稳住重心。竞标或晋升时，把已有成果一柄一柄亮出来。别把每个反对都当敌人，有些只是路过的人流。山长水远，守住这处高地，下一程自然展开。" },
    reversed: { kw: "溃退 / 疑惧 / 放弃立场", love: "杖从手里滑下去的瞬间，防线先在心里塌了。被议论到想退缩时，先问这一局值不值得守。不是所有反对都要应战，有些吵完就散。若已疲惫到握不住，退下阵来休整并不丢人。重新上场前，把为谁而守想清楚再上山。", study: "六面来风时先护住主科，那是你手里那柄。越想讨好所有老师，自己的节奏越容易散。被比较压得抬不起头，就退到半山喘口气。守不住所有的题，就守住最关键的失分点。歇够了再上山，方向感比蛮力更省路程。", career: "防线被轮番试探时，硬扛不如挑重点回击。位置守得太累，先检查是不是站错了高地。放弃一个战场，不等于整场仗都输了。精力有限时，把杖收回而不是插满山坡。退一步重新排兵，比在原地被围攻更体面。" }
  },
  {
    id: "wa08", img: "wa08.jpg", arcana: "wands", rank: "8", name: "权杖八", en: "Eight of Wands", glyph: "✈️",
    upright: { kw: "迅速 / 进展 / 势如破竹", love: "八根杖斜掠金空，消息一条接一条，快也要留一次面对面深聊。并肩坐在倒木上看杖雨，进度飞快时抽空核对三观是否同向。背包和行囊都备好了，说走就走的约会里安排一件安静的共同事务。河谷的水走得急却不喧哗，热恋期过后仍主动约见才算稳。远山静立不动，两人仰头追杖之余，也看看山脚下长期的打算。", study: "杖如飞矢各走一道，多门并行时每门留一页进度单防漏项。仰头数杖的少年提醒你，趁手感火热集中歼灭积累的难点。倒木坐着两位旅人，学累了并肩散步十分钟再回桌，注意力接得上。银发旅伴安静在侧，快节奏里安排每天一段慢整理，错题当天消化。河流穿过峡谷不停，好消息落地后先巩固一轮，别急着加量。", career: "八杖齐发不留空档，多线项目用清单排优先级，逐个击破。天空只闻杖声，沟通一律落书面，口头决定最容易在半路走样。旅人坐看飞杖过顶，急讯满天时先盯住关键一环，其余让它飞。行囊收拾得利落，出差与外派说走就走，回程当天归档记录。河谷开阔水路分明，每天收工花十分钟清点发出的消息防误会。" },
    reversed: { kw: "延误 / 混乱 / 急则生错", love: "飞杖迟了几道，回复慢了些，追问之前先给脑补设一个时限。一人想快一人想缓，并肩的倒木坐出了距离，把期待摊开谈。杖雨斜乱了方向，节奏差半拍时，愿意等的那位先停半拍。背包里翻出旧地图，见面频率谈成双方都守得住的数，别计较秒回。云影遮住河谷，误会生起时当面问一句，胜过屏幕后连发十条。", study: "杖飞得太密互相磕碰，贪快做完不核对，小错越攒越多。仰头看花了眼，乱中先停下，每天留一段专门整理时间。倒木上的行囊鼓胀，资料囤得再多，做对一题比多刷十题划算。河流改了道，期限报得太满就如实改一个，兑现比速度值钱。远山不催云，把速度承诺收回后按新期限走，信任自会回来。", career: "八根杖堵在半空先后坠落，各环节不是延期就是返工，先停催办。杖序乱了就重新排期，留出缓冲余量，把卡点逐个解决。旅人等杖落地才动身，延误发生后同步确切的新节点，别只道歉。行囊共用要分工清点，多线程里谁接哪条线，白纸黑字写清。云开杖落，秩序恢复后再复盘原因，慌乱现场找不出真问题。" }
  },
  {
    id: "wa09", img: "wa09.jpg", arcana: "wands", rank: "9", name: "权杖九", en: "Nine of Wands", glyph: "🤕",
    upright: { kw: "韧性 / 警觉 / 黎明坚守", love: "头缠绷带仍拄杖而立，受过伤再爱时，边观察边给机会。八根杖排成自家篱墙，底线温和而清楚地说出来，设防不等于拒绝。丢盔在地是卸下面子，把上一段留下的警觉讲给对方听。麦田金黄说明熬过了青黄不接，回暖的标志是双方都肯多披露一点私事。回望的姿态不是逃跑，留一半警惕，另一半交给时间验证。", study: "带伤拄杖也不离场，冲刺期靠日程和惯性也要走完当天计划。石墙上八杖列队，把错题按出错频率排一遍，比刷新题见效。绷带是上一轮的勋章，疲劳时先保睡眠，规律本身就在得分。弃刀于地，末段别再开新资料，旧题吃透足够撑到考试。城堡在远处等着，咬牙守住最后关口，关键节点前留两天缓冲。", career: "九杖成阵守一道墙，久战疲惫时把重要交付留好备份和证据。头缠布条的手仍握杖，最后的关口拼体力，排班先排自己。头盔落地人未倒，口头共识易忘，每轮沟通落成书面记录。断刀插土不再用，拉锯已久就别指望奇招，稳守流程防线。夕阳里的城堡未远，守完这段主动申请一次喘息再战。" },
    reversed: { kw: "耗竭 / 疑心 / 放下执防", love: "绷带缠得太厚会闷住伤口，旧经验套在眼前人身上时，先分清人。九根杖守成孤墙，对方靠近你后退，正常的试探被当成敌情。盔甲丢了就别再捡，卸下防备从一件小事试一次信任的成本。长期独扛让帮忙无处下手，给爱人留一个参与的入口。拄杖的手在抖，承认累了不是软弱，说出口比硬撑更稳。", study: "杖还立着人先垮了，硬坐书桌前效率尽失，安排一次完整休整。满墙九杖全是防线也全是负担，砍掉一半科目先保住能拿的分。绷带渗着旧伤，错题越攒越多时停一停，休息也是战斗力。弃盔表明不想再防，复出第一天只排轻任务过渡，别猛冲。麦田熟了可以充饥，状态回稳后再按优先级清积压的错题。", career: "九杖围成草木皆兵，紧绷久了把正常反馈读成敌意，先休整。拄杖变扶墙，疑心最重时的判断偏黑，重要决定推迟到休假后。绷带该换了，把减负理由从扛不住换成保质量，上级更易点头。头盔丢在脚边，别为面子继续戴甲，交接出最外层的杂务。夕阳提醒收工，久战之后先补两天睡眠，再谈反攻的阵型。" }
  },
  {
    id: "wa10", img: "wa10.jpg", arcana: "wands", rank: "10", name: "权杖十", en: "Ten of Wands", glyph: "🥵",
    upright: { kw: "担当 / 重压 / 咬牙前行", love: "横杆上十根杖全压一肩，现实与情绪都揽过来时，累也要说出口。低头看路的人看不见同伴表情，每周留一次不谈压力的并肩散步。村舍灯火是共同的家，把想分担的意愿问一句，别单方面认领。步子慢而稳是担当，但亲密关系本该两人轮换扛杆。影子拖得再长也有太阳在照，坦白压力是给对方搭手的机会。", study: "十杖捆在一条杆上，论文实习考试同压，按截止与分值排序。低头赶路如埋首题海，每完成一项划掉一项，可见进度抗焦虑。村道窄容不下快跑，不可逆的任务先办，能缓交的坚决后放。披风沉但护得住肩，核心科目的吃透标准是能自己讲清。日头还没落，扛住这段就是毕业季，逐件完成胜过整体发愁。", career: "一人挑十杖如兼数岗，把超负荷如实呈给上级，付出要被看见。杆上绳结一根根系牢，兼岗成果留可量化凭证，别成理所应当。弯腰的弧度是专业，但最有成绩时提人手需求才谈得动。村庄在望，急活攒到你手里也要分先后，先办塌了会砸墙的。落日压山仍前行，久扛之后把流程沉淀成手册，让后来人接手。" },
    reversed: { kw: "卸责 / 崩溃 / 学会授权", love: "十根杖压弯了腰，怨气在小事上引爆，开口邀请分担要趁早。扁担咯吱响时别硬撑，把隐忍的具体事件说清，不攻击人格。对方手里也有一副肩，点明一件具体小事让他接过去。路旁的家灯火渐暗，超载前商量卸下一根杖，关系才走得远。影子碎在田埂上，崩溃的信号被认出，两个人一起重新捆杖。", study: "贪多的十杖勒进肉里，报了满打满算的课，学透的没几样。减法从解开一根绳开始，砍掉一半计划，核心科目优先吃透。杆子太重可以分两次背，别把一学期的账当一天赶。低头的姿势久了会僵，做完减法后别因焦虑把砍掉的再捡回。村庄就在坡下，按考试权重配时间，走稳这段就够了。", career: "十杖垂挂挡住两侧视线，事事亲过目，团队就养成了依赖。该解的绳结解出去，从风险最低的环节试放权，小失控不怕。弯腰太久直不起，交接时把判断标准一并讲明，事才不会回流。扁担压肩也压了别人的成长，留出决策位，杂务分出去。暮色里赶路人该歇脚，硬撑到倒下前，主动申请一次支援。" }
  },
  {
    id: "wa11", img: "wa11.jpg", arcana: "wands", rank: "page", name: "权杖侍从", en: "Page of Wands", glyph: "📜",
    upright: { kw: "消息 / 好奇 / 初试锋芒", love: "杖头抽出的嫩叶像新消息，暧昧邀约来了就大方应一次。仰望星空的少年告诉你，好奇心牵着升温，别急着要结论。围巾被风吹向远方，结伴出游的提议落地，先安排轻松简短的见面。脚边火蜥蜴安静发光，热度要观察几日，追问太急反而聊凉。沙漠辽阔金字塔在望，给彼此几天回应时间，路还长。", study: "新杖顶梢冒芽，刚接触的学科新鲜感足，趁劲头搭牢框架。少年仰头看星，不懂就问别怕露怯，新人提问不招人烦。火蜥蜴蹲在脚边不跑，每学一块用自己的话复述一遍。红贝雷上的枝叶是勋章，勤做笔记，把兴趣钉成日程。金字塔由石块垒起，框架立得住靠每天一小块完整闭环。", career: "持杖侍立的姿态接得住新任务，先确认验收标准再动手。消息如星子落在沙漠，面试通知到来时展示潜力而非资历。围巾迎风是出发信号，再小的活也交出一个完整闭环。脚边蜥蜴通体橙亮，第一版结果主动去要反馈，纠偏趁早。金字塔在远处等着，新人阶段多记录勤请教，隐形要求靠问。" },
    reversed: { kw: "画饼 / 分心 / 消息落空", love: "杖梢的叶子蔫了，甜话说得再响，也先看行动落不落地。仰望的人不肯低头看路，忽冷忽热时把节奏拉回自己这边。围巾飘向未知方向，一提见面就推脱，把约会放进对话直接测。火蜥蜴的光忽明忽暗，别加倍热情去焐，观察一段再交真心。沙漠里等不到星，消息落空时收回期待，生活照旧过。", study: "举杖的手换了三次姿势，嘴上学习手里刷屏，目标拆成今天的小任务。少年望着星星忘了脚下，行动是等待焦虑最好的解药。蜥蜴钻进沙里不见，通知迟迟不来时给查看设一个固定时间。金字塔在热浪里晃动，越等越虚，先做对一道题稳住神。贝雷帽上枝叶干枯，反复刷新页面的功夫够背十个词条。", career: "杖顶新芽经不起沙漠的风，前景描绘得美，先问资源与负责人。侍从的个头还撑不起大旗，空头承诺落在文字上才算数。围巾遮不住迷茫眼神，含糊其辞即是警讯，追问时间线。火蜥蜴的光只够照亮脚边，先签小范围协议，用一次履约验证。金字塔的影子在傍晚拉长，画饼充不了饥，试点落地再押大投入。" }
  },
  {
    id: "wa12", img: "wa12.jpg", arcana: "wands", rank: "knight", name: "权杖骑士", en: "Knight of Wands", glyph: "🐎",
    upright: { kw: "行动至上 / 热烈 / 大胆远征", love: "马蹄踏起烟尘，跨越距离的奔赴热烈，先享受再观察耐心。高举的杖是直白告白，坦率有感染力，但也看看对方低谷时的样子。红缨在盔顶飞扬，激情三个月后自然回落，能否转入日常才见真章。绿披风裹着红里子，热烈外面要有恒久的内里，谈一次长远安排。雪山遥遥在望，远征浪漫之余，把回家的日子也说定。", study: "策杖冲锋的姿态宜攻不宜守，锐气正盛时多啃新知识点。马尾带火照亮前路，攻新同时留固定整理时间，冲得快也记得牢。战马四蹄腾空，每天睡前复述住多少才算有效进度。盔下目光专注，难题当前别绕道，一题一题正面突破。荒原辽阔任马奔，计划排到能坚持的强度，热度过后惯性推着走。", career: "骑士提杖出征，外派开拓接二连三，越跑越有干劲时归档战绩。火焰拖在马尾之后，开的新局靠返程后及时沉淀才算落袋。铁甲上的龙纹是招牌，冲刺时维护好后方协作，别只顾前线。燕群绕着盔顶盘旋，随行消息多线，书面记下每条承诺。雪山下的荒原等着路被踩出，趁冲劲把陌生门道录成清单。" },
    reversed: { kw: "莽撞 / 虎头蛇尾 / 中途转向", love: "马冲得太快看不清路况，被激情推着时，把重大决定往后放。火焰尾巴烧得旺也熄得快，承诺听听，重点看兑现了几件。盔面放下就看不见表情，忽冷忽热时直接谈一次步调。披风扬起又落下，今天描绘的未来说变就变，观察一段时日。飞鸟散尽马蹄仍急，别追着跑，站定看对方会不会回头。", study: "起手猛如烈马，跳过基础错题，热度一过就想弃考。缰绳攥太紧马会失衡，计划要排成能坚持的小节奏。火星溅进沙地转眼就灭，热情耗尽后靠既定流程推进。扬尘迷眼看不清雪山，把每日任务量降到疲惫时也能完成。铁甲闷汗不如卸甲，空洞期别硬冲，先睡足再按清单补课。", career: "无鞍的烈马最易翻车，刚起步就嫌慢，转向前先复盘上次烂尾。杖指三处方向，马却只能跑一条，频繁换赛道等于原地踏步。烈焰尾巴烧到披风一角，冒进的成本先算给自己看。燕雀惊散说明阵脚已乱，新方向用业余时间试跑一个月。雪山未近尘土先起，沉得住气才跑得过长途，验证过再全力切换。" }
  },
  {
    id: "wa13", img: "wa13.jpg", arcana: "wands", rank: "queen", name: "权杖王后", en: "Queen of Wands", glyph: "🌺",
    upright: { kw: "魅力 / 自信 / 统筹有度", love: "端坐王座手扶葵花杖的人从不刻意讨谁欢心，你吸引爱意靠的是自身的从容。裙裾上绣的游龙是藏不住的锋芒，约会时不必收敛光芒去成全对方的体面。脚边的橘猫安静蜷坐，它提醒你亲密的分寸是彼此陪伴却互不缠爪。头顶掠过的双鸟像两句悄悄的情话，听到就回应，别把主动示好晾在风里。王座两侧的石狮镇得住场面却镇不住关系，偶尔示弱比全程强势更亲近人。", study: "葵花杖朝上的人天生适合站在讲台前，小组里的主讲不妨就交给你。把要讲的内容像整理花枝那样提前修剪一遍，站上位置才不会临场卡壳。石狮扶手象征你压得住场，但自习的冷板凳仍要一天一天坐热。橘猫蜷在脚边是留白的智慧，热闹分享之后给自己排一段安静复盘。头顶飞鸟容易带走注意力，讲题时收起四处张望的习惯，眼睛回到题目上。", career: "戴葵花冠的人走进会议室自带焦点，场合越重要越要稳住笑容慢慢开口。杖头的葵盘低垂却朝着光，资源从来聚向主动迎光的人，多去有人的局。两侧石狮如同替你镇场的老同事，新场合里先结识能帮你引路的那个人。脚边橘猫提醒你留一只耳朵听别人说话，统筹全场不等于一个人说完全场。绣裙上的龙纹是手腕也是底气，把人情账记细，事后一句跟进胜过当场十句寒暄。" },
    reversed: { kw: "善妒 / 专制 / 光芒黯淡", love: "葵花冠蔫下来时，人才会盯着别人裙上的光，疑心自己的花不开。石狮扶手成了审问的刑具，回消息慢一点就被盘问，爱受不了这种钳制。橘猫受惊会躲，人被醋意追着问也会躲，把质问换成一句我有点不安。头顶双鸟本是好消息，别让猜忌把它们吓走，先说出口的需要往往是陪伴。杖上葵花枯着也别丢掉，承认嫉妒不丢人，讲清楚了光芒才重新亮起来。", study: "目光总瞟向别人进度的时候，自己手里的葵花杖就握不稳了。裙上龙纹再繁复也要一针一针绣，别人的捷径看再多不如补自己的基础。把石狮扶手当成门神，隔绝群里刷屏的进度播报，眼不见心才静得下来。橘猫晒太阳从不焦虑，给它留出固定的发呆时段，情绪落地专注才回巢。冠上花瓣落了就落了吧，从最拿手的一科重新开考，找回掌控感再向外扩面。", career: "王座坐久了容易把独座当独裁，拍板之前先让反对的话讲完。葵花垂首是信号，团队表面顺从时，私下积的怨比烈日晒的土还干。石狮再威风也只是石雕，把决策的担子分给活人担一担，你才不至于累垮。脚边橘猫最懂察言观色，开会时留意那些不说话的人，他们往往看得最清。绣裙华丽遮不住暗火，先安抚共事最久的伙伴，口碑要从内圈一点点修。" }
  },
  {
    id: "wa14", img: "wa14.jpg", arcana: "wands", rank: "king", name: "权杖国王", en: "King of Wands", glyph: "🌟",
    upright: { kw: "愿景 / 领袖 / 开创格局", love: "掌心托起金日的人心里有方向，感情里你肯领路也肯担责，这份笃定最动人。木杖立得笔直，约会的大事你有主张，但别把主张变成替对方写好的剧本。背后帷幕上的双狮像两位长辈，见家长这样的重要场合，提前和爱人统一口径。脚边黑螈安静伏地，引领不是压服，留一段沉默让对方把想说的话攒够。日光照亮侧脸却照不到全部，共同的目标要定期摊开核对，方向变了就及时对齐。", study: "举日者看得远，长周期的复习计划正适合由你来统筹拆解。木杖竖在膝头是定海神针，阶段目标定了就别天天改，稳住节奏先跑一轮。柱廊再宏伟也靠一块块石头垒，战略之外要亲自把最基础的习题做穿。帷幕狮纹提醒你身后有同路人，大课题里敢分工，别把全队捆在自己身上。金光照出的影子也长，节点之间留出弹性，一处卡住不至于全线空等。", career: "托日于掌心的国王负责定方向，关键时刻敢拍板也扛得起结果。木杖不离手，愿景要反复向团队讲透，讲得越透能替你补位的人就越多。石柱之间站得稳，也要每月走下一次台阶，去听一线最真实的反馈。脚边黑螈是低调的执行力，给下属留出施展的缝隙，领袖不必事事亲为。狮纹帷幔挂着的是家底，扩张前先清点人手与粮草，魄力要配上清醒的账。" },
    reversed: { kw: "武断 / 野心失控 / 刚愎耗竭", love: "掌中烈日偏了角度，照得人睁不开眼，你的主导让家里气压越来越低。木杖敲地的声音太响，约会去哪都你说了算，对方的沉默不是同意而是放弃。先把杖放下，下次约会练习让对方起头安排，你只负责补充和捧场。帷幕上的狮子吼给自家人听最伤，重要的决定摆上桌面商量才有温度。脚边黑螈懂得蛰伏，你也学学等待，话说到七分留三分给对方开口。", study: "野心举得太高，脚下的书却没人翻，宏大计划最怕只停在嘴上。金球再耀眼也照不亮空白的错题本，把目标压回每日的任务清单。木杖该拿来丈量进度，每天第一件事排最枯燥的基础练习，做完再谈战略。石柱是前人垒的根基，好高骛远时回头补地基，眼高手低要靠动笔来治。黑螈贴地而行，学着从最小的章节啃起，先证明小事做得扎实。", career: "烈日悬得太近会灼伤人，独断的会议室里没人再讲真话。杖头磨得发亮也撑不起所有决定，给自己设一个诤友，坏消息听完再拍板。扩张的胃口大过账上的金光时，先算清现金流能支撑几个月。帷幕旧狮纹是过去的战绩，功劳簿翻过去，新局面需要新的判断。脚边黑螈提醒你把姿态放低，每月一次坐到同事中间听一线的声音。" }
  },
  // ===== 圣杯 Cups (cu01 - cu14) =====
  {
    id: "cu01", img: "cu01.jpg", arcana: "cups", rank: "A", name: "圣杯王牌", en: "Ace of Cups", glyph: "🍷",
    upright: { kw: "爱意涌动 / 新情 / 直觉敞开", love: "云中伸出的手掌托起满溢的金杯，心动的信号已经到位，只差你开口接住。五道泉水从杯沿泼出去，别把喜欢憋成暗流，一句真诚的问候就是第一股水。白鸽衔着戒指掠过天空，旁人递来的善意带着诚意，接住再慢慢验证合不合。池里莲花各自开放，先把自己的塘养满，溢出来的爱才流向对的人。远山在墙外立着，新感情不必急着翻墙，从一次自然的独处开始升温。", study: "泉水多得盛不住，正像刚点着的兴趣，趁热把它接进固定的学习时段。托杯的手稳稳的，新科目入门就选这股心流正通的时段，效率最高。白鸽绕着杯子飞，灵感来了别让它飞走，手边备一本杂记随时接住。莲花在水面各自舒展，沉浸式学习也要留出自己的水面，别被排课挤干。围墙圈住花园也护住花园，给新热情定个小范围试两周，再决定投入多深。", career: "金杯涌水是创意找上门的征兆，新机会带着心意而来，先确认它与你同频。五股水各自流向池塘，好点子趁氛围正暖赶紧汇报，凉了就要重新烧。白鸽衔环像一封来函，接手新差事前把岗位内容和心里想要的对齐一遍。手掌从云中探出，机会来时姿态要主动，伸出手才够得到杯脚。花园有墙才聚得住水气，热情落地要配一张排期表，别让它四处漫溢。" },
    reversed: { kw: "情感干涸 / 封闭 / 宣泄不畅", love: "杯口朝下时泉水浇不进池子，先承认自己也在干渴，再谈照顾对方。托杯的手酸了就放下，单方面的给予撑不起关系，把需要讲成具体的小事。白鸽停在半空等回应，总收不到信号的那一方会先飞走，别拿沉默试探。池边莲花蔫了是提醒，爱流干涩时先停下来，约一次只谈感受的散步。墙外远山挡不住水声，压抑的情绪找个出口讲出来，别等到决堤。", study: "泉水断流的日子，硬灌新内容不如回看已掌握的章节找回手感。手托空杯也要稳，先把作息调顺，兴趣的潮水会随精力一起回来。白鸽不再盘旋，说明热情被太多应该二字赶跑了，挑一科最有好感的先重启。池水见底就清一清塘，换一间亮堂的教室，情绪常常会随环境松动。围墙成了遮挡，把死板的计划表拆掉一角，留出可以自由翻书的位置。", career: "金杯倒扣流不出水，重复消耗让热情外溢，先看清内耗的源头在哪里。托举的手垂下来时别硬撑体面，找信任的人谈一次真实的感受。白鸽衔来的消息没人拆，团队氛围偏冷时，先回应别人的求助再谈自己。池塘干了莲花合拢，创意枯竭期允许自己停更一阵，去园子外走一走。远山还在墙外立着，换个项目换个场景，心意的泉眼才会重新冒水。" }
  },
  {
    id: "cu02", img: "cu02.jpg", arcana: "cups", rank: "2", name: "圣杯二", en: "Two of Cups", glyph: "🥂",
    upright: { kw: "伴侣 / 结盟 / 情投意合", love: "金与银两只杯沿相碰，第一次对上的眼神就懂了分量。两岸隔溪相望的人肯俯身伸手，关系就有了桥。水中立着的玫瑰与双蛇盘绕的权杖，是感情里愈合与调和的力量。你们不必来自同一片岸，肯各挪半步就够。若刚遇到聊得来的人，把这杯敬出去，别闷在心里发酵。", study: "像两只杯子彼此靠近，找一个能互倒所知的搭档。溪两边的石头各踩一块才稳，文理互补也是同理。讲解给对方听，自己那杯才会被倒满。黄昏的天光温和不刺眼，深度研讨选安静时段更好。别把合作变成对表比赛，碰杯的意义是交流不是胜负。", career: "一金一银两只杯相碰，像两份互补的方案正式签约。谈判桌上各让一寸，成交线就在水中央浮起来。玫瑰压住盘蛇，体面能化解合作里的暗刺。找合伙先试小单，像先碰一下杯再饮尽。远处的鹭鸟站得安稳，急躁的人反而看不见机会落点。" },
    reversed: { kw: "破裂 / 失衡 / 各怀心思", love: "杯子还举着，却已经碰不到一起，距离是装不住的。一方倾身过多而另一方只是伸手，失衡从细节开始。盘蛇的权杖立在水中：旧矛盾没被解开，只是被浪漫盖住。把质问换成一句“我想谈一件事”，僵局才开始松动。若努力后杯子仍对不齐，承认不合适也是一种诚实。", study: "小组里两人各举各的杯，配合成了形式。分工没谈拢就开工，返工比讨论更花时间。把比较心从桌上拿走，碰杯不是干杯竞赛。搭档进度不一时，先对答案再对节奏。实在合不来就各自成题，溪水分开也都能入河。", career: "契约的杯子歪了：口头承诺与纸面条款对不上。合作一方总先饮自己那杯，账目要摆在明处。谈判陷入僵局时，先撤回半步再重新伸手。玫瑰盖不住蛇，体面话解决不了利益分歧。谈不拢就散，好聚好散留得住下次的路。" }
  },
  {
    id: "cu03", img: "cu03.jpg", arcana: "cups", rank: "3", name: "圣杯三", en: "Three of Cups", glyph: "🎉",
    upright: { kw: "欢聚 / 闺蜜 / 庆祝时刻", love: "三人举杯的草地上笑声最松快，轻松的团体局里容易遇见聊得来的人。三只金杯浮在半空没人急着碰响，聚会散场后单独多聊几句再看是否合拍。蓝裙缀星的姑娘笑得大方，敞开自己的状态比刻意寻觅更招缘分。百合开在脚边并不张扬，朋友介绍的对象别因矜持回绝，熟人的背书也是加分项。苹果树压弯了枝头，喜讯值得摆一桌庆祝，感情在热闹里升温更快。", study: "三席人各托一盏杯，学习小组里人人有分工，热闹才不至于空转。中间白裙的姑娘戴花冠主持场面，轮流主讲的角色正适合主动认领。金杯举得高也要放得下，讨论完留一天安静自测，把所得落成分数。脚边南瓜圆滚滚是积累的果实，给小组定个阶段目标，到期一起验收。藤蔓绕树各攀各的方向，同窗互相抽背时别只挑会的聊，短板才是要补的。", career: "三只杯子在头顶亮成一小片星，庆功宴上露个脸，真诚敬谢比群发管用。绿裙蓝裙白裙各美各的，团队里性格迥异的人都能成为你的助力。举杯的手都空着托住杯沿，功劳散给每个具体的人，人气就是这么攒起来的。玫瑰在身后开得正好，士气正盛时顺势提新计划，通过率往往比平时高。秋树染金是一季收成的颜色，阶段成果落地后，记得回头谢同行的人。" },
    reversed: { kw: "社交过载 / 小团体 / 欢庆散场", love: "杯子举得太久手臂会酸，应酬挤满了周末，二人的独处反而成了稀客。三只杯里若混进第四只手，暧昧的苗头要及早挑明，界限划清才算数。笑闹声盖过了悄悄话，散场后那个没聊尽兴的人，才是该认真回消息的。葡萄冠压着蓝裙的肩头，热闹只是表象，每周固定一晚只属于你们两人。百合谢了还能再开，起疑时别当场质问，先讲自己的不安更容易把话谈开。", study: "聚会一场接着一场，自习的椅子坐冷了三张，玩乐邀约要学着婉拒。举杯的手腾不出来翻书，考前一个月最金贵，团体局只当偶尔的调剂。蛇绕着树干悄悄打量，小组里拖后腿的搭子要早点说清分工，或者散伙。南瓜熟透会烂在地里，讨论所得当天整理成笔记，热闹才不算白闹。把改约的话说得软一些，周日补一场安静的互测，友情与进度两全。", career: "三杯酒下肚正事全忘，团建排满日程时，交付是最先掉线的那根弦。星裙和花冠自成小圈，站队的热闹里保持中立，把手头的活做漂亮。举杯的手只朝一个方向，被排挤的苗头出现时，先核对专业度够不够硬。苹果落地也该收摊了，应酬之后留一段无人打扰的深度工作时段。散场的草地只剩杯印，庆过一功就把精力放回正事，口碑靠作品续。" }
  },
  {
    id: "cu04", img: "cu04.jpg", arcana: "cups", rank: "4", name: "圣杯四", en: "Four of Cups", glyph: "😐",
    upright: { kw: "倦怠 / 无视机会 / 内观", love: "树下抱臂的人盯着脚边三杯发呆，递来的第四杯他偏不抬头，眼前人的好常被习惯遮住。三杯在手还嫌淡，倦怠多半是例行公事作祟，换一种相处场景闷局就破。云中递杯的手不打算收回，对新出现的好意先别急着拒绝，放一周再判断也不迟。低头看得清杯底，抬头才看得见递杯的手，心里缺的那块先自己盘点明白。远处山丘平平铺着，感情不是没有波澜，是你太久没有往里走一走了。", study: "抱臂坐在树下的日子谁都有，资料味同嚼蜡时，硬啃不如先合上书本出去走走。脚边三杯摆成旧套路，换一科或换种资料轮着来，新鲜感能帮你顶过平台期。天上递来的第四杯像一节新课，倦怠期至少看一眼再决定要不要上。树影移得慢，进度也显得慢，把学习和真正想要的生活连起来再看意义。草地上的小白花没人夸也照开，回来时挑最感兴趣的部分先读。", career: "三杯摆在面前还提不起劲，上门的邀约先别急着推，写清核心需求再答复。抱臂的姿势关住了递杯的手，拒绝前分清是机会不合还是自己太累。树下坐久了腿会麻，低潮期不宜冲动离职，先在本职里找一个新着力点。云中那只手只递一次，看准的谈话要主动去约，别让犹豫替你做了决定。远山不催低头的人，但它一直在那里，歇够了就起身，机会换了姿势还会再来。" },
    reversed: { kw: "苏醒 / 把握 / 走出淡漠", love: "终于抬手去接第四杯，淡漠退潮之后，日常相处重新显出滋味。松开抱了许久的双臂，把搁置的约定重新提上日程，那次没成的约会就很好。树下坐腻了就起身，主动制造一点小惊喜，回温要从你先动开始。三杯旧酒也能品出新味，说一句“我注意到你的用心”，让回温从瞬间变成持续。云中的手还悬在半空，这次换你抬头，眼神对上，机会才落地。", study: "抬眼再看脚边三杯，滋味和从前不同，卡了许久的地方开始松动。接住第四杯的手要趁热，状态回升时去攻最薄弱的章节，往往事半功倍。树下的位置可以挪了，换间亮堂的自习室，把苏醒的动力落成日程。小白花开了满坡，新资料新思路让人眼前一亮，本周就把小目标写进计划。云上的手会再递新杯，但动力来得快也去得快，别等凉透才想起行动。", career: "第四杯入了手，犹豫许久的事应声落定，主动回应带来第一道转机。抱臂的人站起来了，当初犹豫的选项此刻看得更清楚，重新评估一遍。树荫遮不住回升的太阳，约谈一次上级把想法讲出口，僵局就有了裂缝。三杯仍在脚边没有凉透，被忽略的本职机会擦擦亮，先接住近处的杯子。云中递杯的手等了一会儿，行动快过迷惘，接稳之后再谈下一步去向。" }
  },
  {
    id: "cu05", img: "cu05.jpg", arcana: "cups", rank: "5", name: "圣杯五", en: "Five of Cups", glyph: "💧",
    upright: { kw: "失落 / 缅怀 / 仍有留存", love: "披灰袍低头看泼酒的人，忘了桥上还立着两只满杯，逝去的哭完了记得回头。三杯红酒在地上洇成暗色，难过可以给它设一个期限，到期就转身。桥下溪水还在往前走，眼前人递来的关心别拿旧事当尺子量，对谁都不公平。罩帽压住了视线，允许自己再站一会儿，然后看看桥上没泼的那两杯。远处城堡亮着灯，还在的关系值得好好待，比较之心一起亲密就冷了。", study: "盯着泼掉的三杯懊悔，分数就再难看一遍，复盘先看桥上留着的两杯。地上的酒渍擦得掉，丢分处一条条查，把错题整理成清单比自责管用。灰袍子裹紧是自我保护，情绪最重的当晚别碰新内容，错题留到第二天再理。桥拱弯弯接着溪水，已得分的科目也列一张清单，信心先稳住再谈补漏。城堡在远处没有塌，一次考砸压不垮基本盘，收缩战线从最熟的章节重排。", career: "泼在地上的三杯是沉没成本，复盘会上先把它与残余的资源分开来列。低头久了会忽略桥上的两只金杯，团队里仍有人愿意配合，主动去请。红酒淌成一条线也终会干，预期落空的损失按清单盘点，情绪散得更快。罩帽遮脸谈不成事，把客观意外与自身可改的部分各归各账。山坡上的城堡还立着，收缩战线重新开局，被折损的项目换个打法再来。" },
    reversed: { kw: "释怀 / 转身 / 走出哀伤", love: "把罩帽摘下来的那天，桥上两杯的金色第一次照进眼里。地上的酒干了，转身走上桥，带着学到的界限感投入当下的相处。两只完好的杯子正等着人，复联或新缘分出现时，先讲清从前的结打算怎么解。溪水把泼痕冲淡了，放下不等于遗忘，接受不完美才是新的开始。城堡的门朝桥上开，心门也留一条缝，别在旧酒杯前站成一尊雕像。", study: "离开酒渍走上桥去，才发现基础比想象中牢固，错题本该翻篇了。桥上两杯还温着，用可见的小进步重建信心，复习表按梯度排。溪水带走了那晚的灰，全真模拟来上一场，用实际数据确认回血。抬头能望见城堡了，目标重新变得清楚，薄弱科目排到精力最好的时段。灰袍脱下叠好收起来，别因一次好转就报复性加量，按原计划稳步推进。", career: "转过身后桥上两杯格外醒目，被忽略的资源一件件浮出水面。酒渍留在原地就好，主动联系还能合作的伙伴，把复盘所得变成新方案。石桥比看起来结实，团队的信任还在，回归正轨先发出一封真诚的信。溪水冲过桥洞不停，损失认了账，下一步行动就踩着水声往前走。城堡重新有了轮廓，把这段教训写成流程文档，可靠二字刻回口碑。" }
  },
  {
    id: "cu06", img: "cu06.jpg", arcana: "cups", rank: "6", name: "圣杯六", en: "Six of Cups", glyph: "🧸",
    upright: { kw: "回忆 / 纯真 / 久别重逢", love: "跪地递花杯的姑娘笑得毫无所图，旧相识重逢时，那份熟悉的心动会回来。男孩双手将接未接，重逢的暖意要慢慢递，别一上来就讨答案。六只杯子盛满野花，纯粹的善意先给出去，心动自然有回流的河道。池水映着两岸的树影，旧地重游最易动情，但感情不能只靠回忆来撑。草里的雏菊年年都开，若要重新开始，先核对当初分开的问题如今还在不在。", study: "递出去的杯里花还带着露水，回看旧笔记时，新领悟会自己冒头。像孩子仰头问为什么那样学，好奇心是最耐烧的灯，别嫌问题幼稚。脚边满杯的花要一只只数清，温故之前先对照新大纲，把变过的部分标出来。草坪开阔视野也开阔心境，盲区当新草地走进去，比凭印象快读一遍牢靠。池边风软适合慢读，熟悉的内容搭桥，难的部分才啃得动。", career: "旧日递过花的人如今捧着杯回礼，老同事的推荐是多年口碑的兑现。草帽姑娘蹲下身把杯子放平，老资源回聘时，条款仍要按当下的规矩重谈。六只金杯摆成一圈，往日的善意别急着收回，机会常从旧关系里长出来。池水静静反光，怀旧情怀也能生金，把老经验整理成可交付的方案。男孩接杯的姿态郑重，回应旧日贵人也要及时且正式，礼数即诚意。" },
    reversed: { kw: "沉溺过去 / 停滞 / 向前看", love: "抱着盛旧花的杯子不肯放，新送来的那束就被晾在了男孩手里。童年草坪回不去，眼前人经不起年年拿旧事当尺子量。六只杯都盛着从前，给新关系一段不比较的时间，让当下自己生长。聊天记录和旧物可以收进柜里，争执时别拿出来当武器，那样伤人最深。池水在往后流，心动要朝前发生，回忆安放好了才腾得出双手。", study: "旧笔记里的花干了颜色，当年的经验先小范围验证，别直接套新考纲。少年早已长高，旧尺码的衣服穿不下，最新的真题才是新尺子。六杯摆着不肯挪窝，资料该更新就更新，温故要建立在知新的框架上。池边草地换了几茬花，新方法学起来慢，慢也比站在原地闻旧香强。递出去的花杯要接新的，从最陌生的新章节入手，照出旧经验的偏差。", career: "捧着当年的花杯不放，新局面里它摆不上体面的台面。草帽旧了遮阳就打折，吃老本的成绩单应对不了新的考核。男孩会长成大人，情怀替代不了实力，挑一门当下最缺的技能认真补课。六只杯里的花谢过一轮，让老本行长出新枝，安排一次系统的学习。池水不回头地流，怀念过去的辉煌，不如着手做出下一个拿得出手的代表作。" }
  },
  {
    id: "cu07", img: "cu07.jpg", arcana: "cups", rank: "7", name: "圣杯七", en: "Seven of Cups", glyph: "🫧",
    upright: { kw: "幻梦 / 选择 / 天马行空", love: "云端七只杯各闪着各的光，暧昧选项一多就别急着定心，先多见几次真人。戴冠的人头在杯中向你微笑，脑海里编织的完美剧本，爱上的多半是想象。盘蛇那一杯缠着诱惑，甜言裹着看不清的芯，真实相处才验得出成色。披黑篷的那杯最沉，回避谈未来的对象先放一放，别替对方找借口。山下小路弯弯通往城堡，幻想落地的路要一步步走，把心动放进日常相处里。", study: "七只杯里宝石桂冠俱全，想考的证想学的领域排成一串，精力被选项稀释。发光那颗宝石最夺目，也别被它晃花了眼，先划掉与主线无关的杯子。桂冠代表荣誉也代表虚荣，选方向时分清是真心热爱还是单纯想赢。蛇杯提醒拖延藏在意想不到的选项里，最心痒的那个先放一放。上山的小路只有一条，定下最贴近目标的方向，其余的改天再说。", career: "云里的杯子每一只都闪着前景，邀约琳琅满目时，先问预算人手与验收标准。冠中人头像画饼的承诺，讲得再好听也要落成白纸黑字的条款。宝石杯闪但掂不出分量，华丽的聘书先放一放，追问可验证的细节。黑篷杯里坐着看不清的人，背景模糊的机会宁可多聊一轮再签。城堡在山那头招手，畅想可以留着，本月先让一个最小的方案跑通闭环。" },
    reversed: { kw: "清醒 / 聚焦 / 拆穿幻影", love: "云散后杯子一只只淡去，滤镜碎掉的关系露出本来面貌，选择反而清晰。发光宝石不再刺眼，你终于看清真正想要的人坐在哪一只杯下。桂冠与蛇都收了戏法，踏实相处胜过梦幻剧情，接纳对方的不完美。认清之后仍想留下，就把相处的节奏稳稳落进柴米的日子里。山路尽头城堡显出轮廓，若确属根本不合，反复拉扯不如体面地把话讲清。", study: "七杯缩成一只，从漫天想法里挑出一个，复习计划重新变得具体。宝石的光收进口袋，给目标设时限和检验点，让想象兑换成分数。桂冠的诱惑放下吧，删掉多余的备考资料，只留一条主干走到底。蛇盘着的拖延被识破，本周把计划写进固定日程，先跑一周再说。大愿景换算成每周可测的小指标，上山的路就只剩脚下这一段。", career: "雾气退去，包装精美的杯子露出空底，资源开始往实处集中。那颗发亮的宝石留到最后确认，虚的项目退潮，腾出的力气投向实处。冠中人头不再许诺，少谈蓝图多交成果，清醒期的口碑比故事更稳。黑篷杯子最先被略过，说不清细节的机会再便宜也不接。城堡有了确切的路线，集中力量推进最可行的项目，用验证过的结果说话。" }
  },
  {
    id: "cu08", img: "cu08.jpg", arcana: "cups", rank: "8", name: "圣杯八", en: "Eight of Cups", glyph: "🚶",
    upright: { kw: "主动离场 / 追寻 / 不满足", love: "八只杯子摆在山坡上，安稳给的东西都在，唯独心里还缺一块。红袍旅人握杖远行的背影提醒你先诚实，空缺别算在对方头上。想暂时一个人走走就明说这是充电，别让沉默被当成冷战的开场。谈话挑河谷安静的时候进行，只讲自己的感受，不翻旧账。新月照着的山路要走多久，出发前两人一起把期限谈清楚。", study: "第八只空杯放在线上，旧成绩已经喂不饱你，更难的领域在招手。带着已打好的基础走山路，不必把从前清零重来。转方向之前先去旁听几次，分清是真心向往还是只想逃离。新科目像夜行河谷，给自己一个月适应期再判断去留。木杖拄地的声响要踏实，把每天可执行的小步写进计划里。", career: "红袍人离开八只金杯的背影，写着你反复说起的那句不甘心。走之前把存款、交接和退路逐项算清，追梦也要有粮草。递辞呈像旅人转身，挑体面时机把手上的活收出交代。新月在山口挂着，理想值得规划，不值得只当抱怨说。若暂时走不了，先在现岗位认领一件真正想做的事。" },
    reversed: { kw: "徘徊 / 回归 / 不敢启程", love: "转身的人又走回杯边，想走走不了的拉扯最磨真心。怕的是失去还是改变，红袍兜帽下没人替你回答。决定再试一次就设个期限，像给山路立块里程碑。舍不得的常是投入本身，把账本合上再看前方河谷。别在原地耗着双方，新月不升不落的日子先谈底线。", study: "八只杯子重新排好，退回旧轨道的人心里仍有不甘。想换的方法停在嘴边时，用一次低成本试听代替脑内推演。两边都不深耕最可惜，选定一条山路认真走三个月。河谷夜路怕黑的话，找走过的人问问真实日常。木杖放下又拿起，犹豫超过一个月就该逼自己拍板。", career: "离开的勇气攒不足，留下又天天内耗，像走到山口又折返。简历像行囊悄悄更新，市场反馈会替你回答敢不敢。抱怨当背景音久了会听不见信号，给自己定一个改期。决定留下就争取一次想负责的项目，让日子有奔头。八只杯还在原地，走与留都要有个明确日期。" }
  },
  {
    id: "cu09", img: "cu09.jpg", arcana: "cups", rank: "9", name: "圣杯九", en: "Nine of Cups", glyph: "😌",
    upright: { kw: "满足 / 愿望成真 / 享受生活", love: "九只金杯码满木架，红衫人抱臂含笑，情感账户正丰盈。被爱包围的得意时刻，把感谢当面说出来给身边人听。喜悦从杯沿溢出来时，也留一次深聊给细微的变化。心里有愿望就坦然开口，像桌上玫瑰摆在明处。顺境最易疏忽对方，约一顿认真做的家常饭保鲜。", study: "九只金杯在架上排成三层，学习进度也终于顺了。红衫人抱臂的笑提醒你享受此刻，别急着焦虑下一步。状态正好时啃一道难题，顺境里的突破最见成效。把有效的方法抄进笔记本，日后低谷靠这份清单回血。桌上百合开得从容，给愿望配一个具体日期去兑现。", career: "木架上九杯满列，口碑与业绩这回一起到位。抱臂而坐的从容是底气攒出来的，谈晋升正合适。庆功时点到每个具体的人，福气分出去才长久。悬挂的干草与灯笼是旧积累，别忘回馈托过你的同事。愿望成真也别松看守，把成果挂到明处备查。" },
    reversed: { kw: "奢求 / 空虚 / 得意过早", love: "杯架满而笑容发僵，物质热闹填不齐心口那个洞。用排场代替陪伴之前，先问自己到底渴什么。把真实需求说出口，像把陶罐里的水倒进杯里。得意太早易生变数，好消息等成果落定再讲。撤掉一场应酬，换两人安静吃一顿桌边的饭。", study: "架满九杯偏要数缺口，尝到甜头就停笔是最深的坑。心愿迟迟不兑现，多半顶层那只杯还空着。小成就之后安排一次严格自测，查查深层的账。把心愿按架层拆成阶段任务，做完一格再庆祝一格。别收藏感动当进度，今天先完整做一套真题。", career: "红衫人笑得过早，杯架未稳就先声夺人招来攀比。成果未定之前低调推进，喜讯公布太早容易招变数。像清点架上杯子一样检视开销，满盈感别滚成下季度负担。桌上玫瑰与百合各摆一色，排场做多了反遮住真相。想被看见就先交出可核对的结果，庆祝排在数字确认之后。" }
  },
  {
    id: "cu10", img: "cu10.jpg", arcana: "cups", rank: "10", name: "圣杯十", en: "Ten of Cups", glyph: "🌈",
    upright: { kw: "家庭美满 / 和谐 / 情感圆满", love: "十只金杯在云空排成两列，一家人仰头同望，圆满有了形状。搂腰举手的夫妻给你示范，激情沉淀后要讲踏实归属。谈婚论嫁前把家务分工说清，别让和美败给琐碎。给彼此留一个眼神暗号，家人聚会时它比客套好用。草屋炊烟日日要添柴，小仪式就是圆满的柴火。", study: "云上的杯子稳稳排着，家在后头，书桌前心无旁骛。无牵挂的阶段最适合攻长周期任务，一鼓作气啃硬骨头。向帮忙分担琐事的家人道谢，稳定的后方同样要经营。孩子伸手够杯的雀跃，值得你在考完当场分享。河谷与远山各在其位，把学习与生活排成互不冲突的两列日程。", career: "十杯高悬像彩虹拱门，团队如家的愿景要挂在明处。仰头同笑的夫妻给出合伙的样子，信任要当众表达才牢。长期项目进了收获期，把经验写成方法传给新人。亲密时更要明确功劳分配，别让情分慢慢磨成怨气。茅屋烟囱不断火，共同愿景靠日常小事续着烧。" },
    reversed: { kw: "裂痕 / 理想落差 / 修复家人", love: "杯列还挂在天上，屋里的对话先冷了下来。孩子在院里喊人，屋里却各说各话，小隔阂越积越深。从草屋那顿用心做的晚饭修起，先恢复对话再谈圆满。这个假期的安排就很好入手，挑一件最小的事先聊开。别等节庆才聚，平日一通电话比团圆饭更易破冰。", study: "十只杯隔着云够不着，家事的杂音飘进了书房。坐在桌前想着门外时，把目标调小到每日底线。跟家里人约定固定时段，明说这段需要不被打扰。主动分担一件院里的琐事，换一夜安静再回书桌。炊烟散了还会再升起，支持系统拆了重建也来得及。", career: "天上的杯子排得整齐，屋里的人各想各的。表面客气盖住分歧时，请每个人会上讲一条顾虑。大愿景谈不拢，先把最近一季度的小目标统一。茅屋的门要开着讲真话，裂痕正是修复的起点。河谷分了支流终会合，重建认可从一次公开感谢开始。" }
  },
  {
    id: "cu11", img: "cu11.jpg", arcana: "cups", rank: "page", name: "圣杯侍从", en: "Page of Cups", glyph: "🐠",
    upright: { kw: "好消息 / 童心 / 创作萌动", love: "少年低头看杯中跃鱼，青涩的示好笨拙却真诚。收到浪漫讯息时，从共同兴趣接话最容易延续。别急着定性心动，约几次真实相处看看成色。远处帆船载着小好消息，回应趁早别晾着。沙滩野花开得随意，表白不必排练，自然接住就好。", study: "杯里跳出鱼的那一刻，灵感找上了爱发呆的人。备一本收集册，把闪现的创意落成小作品。新学科入门时多动手少空想，兴趣靠一次次正反馈续航。像沙滩野花那样随手记，先让直觉有地方落脚。帽上那朵小花是好奇心，别嫌它顶不起大用处。", career: "蓝袍侍从捧出带水花的消息，新芽般的提案被看见了。展示不完美的初稿时，附一组小数据让说服力站稳。贵人递来小惊喜，及时回复是第一遍浇水。海面帆船还在远处，机会靠岸前先把工位收拾好。学那少年俯身的姿态，从旁观者变成动手的人。" },
    reversed: { kw: "幼稚 / 情绪化 / 一厢情愿", love: "鱼跃出杯溅湿了幻想，爱的可能是自己写的剧本。忽冷忽热时别急着补剧情，先冷静观察一周。甜言收下就好，重要承诺留到相处有底子再谈。少年低头不语，猜心思像望错帆影，把话问出口才准。远处帆船迟迟不进港，与其岸边守望不如改约见面。", study: "情绪像杯中水晃来晃去，灵感来了才肯动笔的日子该收束。建一套固定小流程，先完成再等状态。状态差时拿机械性任务热身，笔动了灵感就跟上来。像那尾鱼先跳起来再说，允许初稿难看，写完再修。别让沙滩野花替日程表开花，先定好每日动笔的时刻。", career: "该来的消息像迷航的船，延迟失真后更要当面核实。玻璃心被一句批评扎到时，先记要点过夜再回。等进度焦虑就直接问一次，比独自猜来猜去高效。杯中鱼翻腾水花，情绪与专业表现要分开放。侍从的蓝袍还稚嫩，把委屈说给信任的人再上班。" }
  },
  {
    id: "cu12", img: "cu12.jpg", arcana: "cups", rank: "knight", name: "圣杯骑士", en: "Knight of Cups", glyph: "🕊️",
    upright: { kw: "浪漫 / 邀约 / 温柔递情", love: "白马缓步而来，金杯高高举起，浪漫邀约带着仪式感。接连的邀约是明确信号，回请一次让关系平衡。享受深情时聊一回现实话题，看它落不落进日常。盔羽在风里招展，心动可以说出口，节奏别交给他一个人。递杯的手戴着甲，观察诚意要比听情话用心。", study: "骑士以热爱为马，人文科目忽然开了窍。把知识点串成故事记，审美是最持久的燃料。灵感像马步有快有慢，用固定时段兜住波动。斗篷上的杯月纹样是积累，每天抄一段喜欢的原文。举杯之前先踏稳草地，文艺也要靠动手练习打底。", career: "执杯递出的姿态优雅，提案打动了会议室。人脉牵线送来机会，响应要快让能量流动。情感之外附上执行表，浪漫才配得上落地。披风绣满金杯与月亮，好意象也要配一组可核的数据。白马不疾不徐，被邀约时先问清责任再应承。" },
    reversed: { kw: "空想 / 暧昧 / 华而不实", love: "杯举得高却迟迟不递到手，承诺总差临门一步。情话满分的骑士也会绕路，看行动别看台词。谈位置就用具体请求，比如每周固定见一面。再度失约时停止替他找理由，平静说出你的底线。马蹄印停在溪边打转，暧昧拖久了要摊开谈。", study: "白马驮着幻想跑，收藏的干货一题没做。理想分数挂在斗篷上好看，桌上要摆当天最小的任务。每天留一小时扎实动笔，热爱需要练习承载。感动式资料停止囤积，今天就完整做一套真题。盔甲再亮也挡不住困意，规律作息比仪式感管用。", career: "华美的杯照出空方案，一推敲就露怯。口头承诺迟迟不落袋，盯住节点与文字。延期两次就该正式面谈，别替对方找台阶。马披银甲走得慢，成本与风险先测算完再汇报。斗篷绣月遮不住短板，补上数据方案才立得住。" }
  },
  {
    id: "cu13", img: "cu13.jpg", arcana: "cups", rank: "queen", name: "圣杯王后", en: "Queen of Cups", glyph: "🦢",
    upright: { kw: "共情 / 直觉 / 温柔包容", love: "她低头看杯的安静模样，是被懂得的安心感。玫瑰冠下的人接得住情绪，也请你把自己的感受说出口。偶尔主动示弱，让倾诉不再单方面流。杯底的软垫提醒爱要垫细节，纪念日里一句回应就是回响。水面轻轻托住椅脚，她接住情绪的本事值得你学。", study: "捧杯如捧一件易碎的灵感，感受力成了学习优势。人文与心理类内容此刻读得格外透，趁热整理框架。用结构化笔记给直觉搭座，灵感才沉淀得下。天使雕饰立在椅背两侧，把读到的观点讲给同伴听。裙摆浸水而不湿，情绪顺时学新章，不顺时复习旧页。", career: "王座安放在水中央，她在团队风波里稳得像定音鼓。客服、疗愈、教育这类连接型工作，正吃她的共情本事。矛盾起时出面调停最有效，但别接下所有人的情绪。双手捧杯的姿势适合汇报，先讲感受再讲方案。玫瑰冠是软影响力，日常一句体谅就攒下口碑。" },
    reversed: { kw: "依附 / 情绪泛滥 / 耗竭", love: "杯抱得太紧，水满则溢，情绪泛滥先淹了自己。一味体察对方时，沉默的不满在软垫下积累。从每天说一个小需求练起，被照顾也是必修课。察觉自己在内耗就暂停付出，先问问自己累不累。别学水面无底线托着椅脚，包容要有边界线。", study: "湖水漫上座脚，杂事与情绪轻易入心，久久静不下。先写一段心情倒掉暗涌，再回到书桌前。设一段边界时段，安顿好情绪再安排任务。多愁善感可以用在材料题上，先体会作者处境再分析。玫瑰冠蔫几瓣不要紧，状态差的日子只保底线进度。", career: "王后累了也要微笑，老好人的角色悄悄耗空杯子。给接活设一个额度，透支之后质量先垮。同事来倾诉时给到建议即可，不必替人背责任。温和地拒绝一遍试试，天不会因此塌下来。椅背天使各守一边，你也得给自己留个帮手。" }
  },
  {
    id: "cu14", img: "cu14.jpg", arcana: "cups", rank: "king", name: "圣杯国王", en: "King of Cups", glyph: "🌊",
    upright: { kw: "情绪成熟 / 宽厚 / 驾驭波澜", love: "一手执杯一手握杖，他把深情与担当同时稳住。浪拍座基而面色不变，有分歧时先安抚再讲理。珍惜这份成熟，也主动把你的欣赏说给他听。重大事项仍要一起商量，稳重的人偶尔替你拿主意。脚边那朵落下的玫瑰是软处，你的坦诚能让他卸下架子。", study: "海面起伏而王座不动，长线备考靠的就是这份定力。情绪不为一次分数起落，按周推进的计划别乱。定期复盘像国王望船，让方法持续迭代。偶有烦躁时先回看源头，别让一次波动变成弃考。权杖端在手里，深度思考也要有章法撑腰。", career: "惊涛只拍到座前，危机里他的语速就是全场定心丸。以同理心推动谈判，分寸感是圆融的手腕。授权与培养要跟上，宽厚需要制度长久承载。远处帆船各走各路，他放心把航线交给部下。金冠束发不遮眼，听得进坏消息的人才镇得住场。" },
    reversed: { kw: "暗涌 / 操纵 / 情绪失驭", love: "表面温和内里翻浪，冷暴力在沉默里涨潮。有情绪不坦白，用暗示让对方去猜，亲密在暗流中变凉。识别以退为进的控制，把话谈开才重见温度。自己爱生闷气的话，练习把情绪翻译成需求再开口。杯里的水晃出来才看得见，别等涨到座前才说。", study: "心里暗涌表面按部就班，烦躁在悄悄偷走效率。先写三分钟情绪日记倒掉暗涌，再翻开书本。规律作息是压浪的杖，睡够了再谈计划。别用完美日程压迫自己，留出弹性时段更可持续。座下玫瑰提醒柔软，苛责分数前先问问状态。", career: "喜怒藏得比海还深，驭下以柔术让人处处揣测。重要沟通留下文字记录，给猜测少留空间。有心结就当面陈述事实，暗示与迂回只会加深隔阂。权杖举得太低照不亮航路，信息透明才养得出信任。浪若总拍向同一个部下，该请上级把话说开。" }
  },
  // ===== 宝剑 Swords (sw01 - sw14) =====
  {
    id: "sw01", img: "sw01.jpg", arcana: "swords", rank: "A", name: "宝剑王牌", en: "Ace of Swords", glyph: "🗡️",
    upright: { kw: "洞见 / 决断 / 理清真相", love: "云中伸出的手握剑直插草地，一场坦白局该落地。把话说透要挑双方平静的时辰，只陈述事实不带刺。剑柄顶端的冠冕提醒坦诚是体面事，诚意从澄清开始。谈开后看行动是否跟进，共识才落得进日常。一次说不透就约下一次，别让坦白变成审问。", study: "剑尖点地的那一下，像抓住核心概念的顿悟。趁热把逻辑用自己的话写一遍，灵感才算沉淀。思路锋利的日子去攻最难一章，清掉积压的疑点。光芒散开之前先收拢，把顿悟写成三句笔记。框架比题海更快，隔天讲给自己听检验是否真懂。", career: "执冠之手把剑立正，斩乱麻的决断就在此刻。结论写成一页纸推进，别让共识在拖延里散架。分歧点单独标出，让反对的人把话说完再定稿。决策落定就及时同步各方，信息差是方案变形的源头。双山对峙而一剑居中，两难时先定标准再选边。" },
    reversed: { kw: "割裂 / 混乱 / 滥用锋利", love: "剑倒竖着伤人，气头上的话专挑对方痛处落。一句顶十句之前停顿半分钟，刀该对着问题而非人心。说过的重话要认真道歉修补，别用沉默拖长刀口。云端的手也会抖，锋利用错地方只剩裂缝。语言攻击成了习惯的话，两人一起正视这个模式再改。", study: "剑身乱晃反光，越钻牛角尖思路越散。合上书默写记得的，先补基础漏洞再谈技巧。抄笔记的勤奋盖不住空洞，哪里卡住就回哪里。把当天目标缩成一个具体问题，专注才有落点。冠冕再美也虚，学完一节先自测再翻页。", career: "出剑又收剑，朝令夕改让团队无所适从。先把最有把握的几点书面敲定，细节在执行里补。已宣布的改动尽量别再翻转，公信力比一次优化值钱。云中递来的议论先核对事实，别让猜测替你下结论。剑尖朝天站不稳，观望太久机会会顺草坡溜走。" }
  },
  {
    id: "sw02", img: "sw02.jpg", arcana: "swords", rank: "2", name: "宝剑二", en: "Two of Swords", glyph: "🙈",
    upright: { kw: "僵局 / 权衡 / 蒙眼抉择", love: "蒙眼布系在额前，两柄剑交叉挡在胸口，你把想说的话也一并拦下了。看不清对方的表情时先别急着选边，僵坐多久天平也不会自己倾斜。海边的风一直在吹，裙摆都动了，僵持的局面也需要一个会动的时刻。想知道偏向哪边，可以约定各自把两条路的好处写下来，再一起念给对方听。头顶的月牙照不亮抉择，那就把蒙眼布松一寸，先看清手里剑柄的温度。", study: "两种复习法像左右手各握一剑，交叉在胸前谁也不让谁。蒙着眼刷题只会原地僵坐，先把两种方法各自的耗时摊开来看。石凳坐得凉，脑子不能跟着凉，给自己定一个只试一种方法的短周期。海面上两把剑的影子晃成一片，选项看着多，能同时走的只有一条。羽毛别在额前是轻的信号，做决定前睡一觉，醒来哪边沉就往哪边靠。", career: "谈判双方各亮一剑，剑尖相抵，谁也进不了半步。你坐在石凳上的姿势越稳，越容易被当成默许，适时开口说一句再议。蒙眼布挡住的是表情，不是条款，先把分歧逐条记在纸上。海湾的水看着平静，暗流都在剑影下面，休会期间去核实彼此的底牌。月亮只露半边，信息不全时别给最终答复，约一个双方都能到的期限。" },
    reversed: { kw: "摊牌 / 破局 / 真相刺眼", love: "蒙眼布落下的一刻，交叉的双剑终于分开，摊牌就是这么一个动作。真相像剑尖闪过的一点寒光，疼一下，总比隔着布条猜下去强。别在话说出口的当晚要结论，海风会吹散火气，明早再谈细节。从石凳上起身让出半边，给对方一个坐过来的位置，僵局就破了。摊完牌请把听到的话复述一遍，很多扎人的刺其实出在听错。", study: "眼布一摘，积压的新知识像海浪一样拍上来，先挑一科站稳。两柄剑分开放进鞘里，一次只学一条主线，支线等框架立稳再碰。信息涌来时抬头看看月亮，它也只亮一半，允许自己有盲区。把没听懂的名词先归进主干框架，像给两柄剑各配一个鞘。破局后的头几天像刚离石凳，腿麻进度慢，那是换方向的正常代价。", career: "休会结束再进会议室，眼布该摘了，把亮出来的底牌一条条记清。交叉的剑一分开，中间的空位就是新条款的落笔处。真相刺眼如剑光，先把最难的条款写进纪要，逐条核对再签。石凳边的海路已经通航，谈崩也留一条改道的余地给彼此。破局之后趁热把分工写清，别让剑再交叉回原处。" }
  },
  {
    id: "sw03", img: "sw03.jpg", arcana: "swords", rank: "3", name: "宝剑三", en: "Three of Swords", glyph: "💔",
    upright: { kw: "心碎 / 伤痛 / 直面哀伤", love: "三柄剑穿在心上，雨从乌云里落下来，伤心就让它下一阵。别替插心的剑找理由，先承认疼，再谈这段关系哪里裂了缝。雨幕和金光在同一片天上，两种情绪可以并存，不必装作已经痊愈。头几天只安排吃饭睡觉和找人说话，重话留到云散再讲。若决定谈开，把每柄剑对应的一件事写清，一次只谈一个话题。", study: "一次失利像一剑穿心，错题摊开在雨里，凉得刺眼。三柄剑各扎一处漏洞，把它们归成三类，痛处往往就是提分处。给自己限两天的阴天，哭完把试卷按知识点重排一遍。云层的雨总会过，金光从下方透出，两周后回测同类题看变化。别在情绪最低时改学习计划，先让伤口结一层薄痂再动。", career: "坏消息传来像三剑扎胸，先把手头的事按紧急度排成一列。乌云压着雨往下落，通报团队时把已知和未知分开讲。金光在最下面，坏消息里也带着线索，记下这次暴露的短板。先把清算交接这些急务落地，像给心口的剑按住止血的那只手。云散之后复盘这轮应对，把管用的止损动作写进流程。" },
    reversed: { kw: "拔剑 / 复原 / 执痛不放", love: "心上的剑柄已被握住，拔出来会带出一声闷疼，疼说明在复原。别把拔下的剑再摆回胸前反复端详，旧事只谈一次就算谈过。雨云正在退场，偶尔飘过一阵也正常，不必当成重犯。金光漫上来了，疗愈按自己的进度走，不用配合别人的期待。再提起那次伤害时，换成说我需要什么的方式，剑就只剩剑柄没有锋芒。", study: "三柄剑一根根离开心口，重做旧错题就是拔剑的动作。剑拔净了不等于满分在即，从有把握的题目开始找回手感。雨后的天光适合背书，把每次小胜记进清单对冲那次打击。剑拔光了恐惧还会在云里打转，等它声音小了再碰难题不迟。伤口结痂处最痒，旧失分的板块反复回测才算真补上。", career: "穿心的消息成了过去式，把因果写成一份复盘笔记收进抽屉。拔剑要挑时机，接手新任务前先讲清这次的教训与改进。云缝里的金光够用了，恢复期接的小单子是重建信心的砖。别替拔下的剑找责任人，笔记里只留事实、决策和下一步。余痛还在时少开长跑会，短会快决，让节奏替你护住旧伤。" }
  },
  {
    id: "sw04", img: "sw04.jpg", arcana: "swords", rank: "4", name: "宝剑四", en: "Four of Swords", glyph: "🛌",
    upright: { kw: "休整 / 静养 / 蓄势待发", love: "他把剑挂上木架躺进石台，暂停不是弃赛，是给思绪让路。约定一周少联系，争吵的余音像彩窗的光，落下来会晕花。盔甲没脱就睡了，想清楚再复出，复谈前各自列好最在意的事。石台边的百合开得安静，独处那几天把作息慢慢补回来。向日葵圆窗转了一周再交换结论，先说我想到了什么。", study: "三柄剑高挂在木架上，一柄横在身侧，书桌也该有停战的架子。背不进的那晚就熄灯，记忆像睡着的骑士，在梦里自己归位。彩窗的光斑落在地上，复习后留一段空白，别把每分钟塞满。石台上躺平的是身体，醒着的该是计划，复出当天先做轻复习。把休整写进日程像挂好四柄剑，睡够再碰新难题。", career: "项目按下暂停，像骑士躺上石台，剑归架，人归位。彩窗两侧的光各自亮着，趁空档把收到的反馈分门别类收好。别把休整当边缘化，石台上的安静正适合看清全局。横放的那柄剑是随时可用的底气，把技能短板列成清单备着。对外只说节奏调整，等石台睡够再带着方案起身。" },
    reversed: { kw: "躁动 / 过劳 / 强行复出", love: "剑还挂在架上人就坐起来，冷静期没过就复谈，旧话会重演。盔甲没卸利索，先问自己急着开口是想念还是慌。石台凉，心气更急时把复谈推迟几天并不丢人。彩窗的光晃眼，睡眠没补够时做的承诺容易褪色。真要用剑时手会抖，先把作息养直，再谈谁来让步。", study: "剑没挂稳就回书桌，一页书翻三遍字都没进脑子。架上的剑别急着全摘，每天先只领一小块任务练手。彩窗外的太阳晒到眼皮了，补觉和运动排在刷题前面。强行复出的错题像没睡够的眼睛看剑，越看越花。每天打卡记录状态，像看日轮转过彩窗，抬头了再加码。", career: "躺够了才起身，伤没好就冲上一线，小错会连着出。挂剑的木架还在原处，回归首周只接有把握的活。跟上级坦白限度不是卸甲，是把排期拉回可行的轨道。彩窗的花纹要凑近才看清，状态不稳时先做有检查环节的事。康复的标准看精力不看日历，撑满负荷只会再躺回去。" }
  },
  {
    id: "sw05", img: "sw05.jpg", arcana: "swords", rank: "5", name: "宝剑五", en: "Five of Swords", glyph: "🗯️",
    upright: { kw: "冲突 / 险胜 / 代价之赢", love: "他抱着两剑得意地笑，两个背影已披着斗篷往湖边走。吵赢的那句话像留在草里的三柄剑，拔不拔都扎眼。阴云只盖住半边天，赢了立场输了温度，冷场比争吵拖得更久。下次话要压过对方前，先想想湖边那两个低头的背影。真在乎就别学那个笑容，把得意的劲头换成先递一步。", study: "藏笔记使绊子的较量，像身后插进草地的剑，看着赢实则耗。他抱走两柄只留三柄，比较心带走的时间比留下的多。阴云那头有人低头走开，输家名单里其实没几个真输了。把较量改成和昨天的自己比，每日错题统计是更稳的记分牌。险胜的名次要不得底线，取巧的空洞会在大考时漏风。", career: "抱两剑笑的人，身后是空了三柄剑的阵地。内斗赢来的位置，坐上去像踩在插剑的草地，浑身不自在。两个披斗篷的背影离开时，项目里的人心也少了一块。争之前先算代价，公开的规则与事实是唯一的剑鞘。把竞争引向阴云外那片开阔水面，利益分清楚才算胜。" },
    reversed: { kw: "悔悟 / 休战 / 放下胜负", love: "他把剑插回土里转过身，休战的第一步总得有人先走。低头不丢人，那是在告诉离开的背影，关系比面子贵重。阴云散开一条缝，把到嘴边的反驳先咽下一半。停战后要把真需求讲明白，否则只是把问题按进泥里。轮流说一次各自的底线，像把剑一柄柄插回草地归位。", study: "抱着的两柄剑也放下了，退出比较那天书桌格外安静。走开的背影不必追，按自己的薄弱点重排课表。草地里剩下的剑坑，填法是每日固定的小任务。想回头攀比时，看看近一周的完成记录就够了。化敌为友不亏，约那个对手互相讲一遍各自的盲区。", career: "笑声收了，两柄剑递还回去，和解的窗口正开着。会面时摆明各自诉求，给离场的背影留一个回头的台阶。阴云下的湖面起了风，旧账翻一页就压一页。把对手变成伙伴，共享目标写进第一行纪要。停战协议要有分工边界，防止插过剑的草地再被踩乱。" }
  },
  {
    id: "sw06", img: "sw06.jpg", arcana: "swords", rank: "6", name: "宝剑六", en: "Six of Swords", glyph: "⛵",
    upright: { kw: "渡离 / 疗愈之旅 / 渐入佳境", love: "六柄剑插在船舷当桅杆，伤还没好利索，船已经离岸。披斗篷的两个人靠在一起，过渡期少谈结论，多保持规律联系。撑篙的人不看回头岸，旧事在船上就让它坐着，别再加重量。水面平静是这段感情的进度条，慢不等于停。云开处露出金色天光，到了新岸再给关系下判断。", study: "换方法的过渡期像这条静水河，成绩先晃一晃再抬头。六柄剑立在舷边挡风，新流程先用满一个月再说。船上的孩子要抱稳，基础模块优先，支线等靠岸再碰。撑篙的节奏比水流重要，每日定量比猛冲更能渡过去。对岸的树影已经近了，正确率与稳定性双升才算渡过。", career: "调岗的船离岸时，是非留在身后那片乱石滩。舷边插满剑像一道栅栏，把旧纠纷隔在水声外面。低头依偎的两个人提醒你，先安顿人心再谈新布局。撑篙的手不急着用力，过渡期少做重大承诺。云开的方向就是新环境的规则，安顿后逐条去摸。" },
    reversed: { kw: "搁浅 / 旧患复发 / 无法启航", love: "船在原地打转，因为没谈清的旧账跟上了船。舷边的剑挡得住风，挡不住斗篷里那句没说出口的话。水再静也到不了对岸，启程前把旧账摊开当面谈完。撑篙的人累了就换一换手，别让一个人划完全程。若同一件事又吵起来，说明心结还在舱底沉着。", study: "换了资料船还是那条旧航线，方法不改就搁浅在原地。六柄剑成了栅栏困住视线，先自测定位真正的卡点。别把逃避说成调整，新资料设两周观察期再定去留。篙插得再深，方向错了也只是搅浑静水。孩子还在舱里等，先把主干框架搭稳再谈拓展。", career: "行程一再推迟，旧阵地的问题正在乱石滩后发酵。舷剑的倒影晃了又晃，搁浅时先把遗留事项列成清单。撑篙的人回头望，那是问清阻碍卡在哪个环节的信号。交接人没定就开船，责任会泡进冷水里发胀。云重新合上也不慌，靠一次推动再解一根缆。" }
  },
  {
    id: "sw07", img: "sw07.jpg", arcana: "swords", rank: "7", name: "宝剑七", en: "Seven of Swords", glyph: "🦊",
    upright: { kw: "策略 / 隐秘 / 智取变通", love: "他抱着五柄剑回望营地，心里那点算计月亮都看见了。小秘密像帐篷里藏的灯，点一次可以，常藏就要谈。留在地上的两柄剑是说得出的一部分，先分清你藏的是哪种。学他迂回之前先想清，对方要的是诚实还是和气。涉及承诺的事别学他夜行，当面说清比什么巧计都稳。", study: "抱走五柄留两柄，抓重点的策略也得看地基漏没漏。夜路看月亮，学习看考纲，捷径只走在已掌握的路上。帐篷里的火还没熄，基础题要亲手过一遍再谈技巧。回望的眼神说明心虚，每阶段留一次综合模拟自查。省下的功夫要还到暗洞里，智取的前提是账算得清。", career: "他不硬碰营门，抱着剑绕行，谈判也常有迂回的一手。两柄剑插在明处作幌子，情报却要走正规渠道核实。月亮底下枯枝横着，计谋要设一条不失信的底线。声东击西的招数，用在双赢方案上才叫策略。布局前把对手动静的来源查清，误判会让自己陷入被动。" },
    reversed: { kw: "败露 / 回头 / 弃暗投明", love: "怀里的剑快抱不住了，营地的帐子一顶顶亮了灯。赶在传闻之前自己开口，把隐瞒的初衷讲清楚。剩下两柄剑也拔了放回原处，坦白比圆场更能挽回信任。枯枝绊脚的时刻别推给别人，只讲事实和感受。月亮落下去以后，允许对方反复确认而不显出不耐。", study: "押题的捷径在考场上露了馅，怀里的剑掉了两柄。回到课本从例题过手，踏实的分数才守得住。帐篷的火照见夜行人，每周留一次闭卷自测验成色。怀里的剑掉了才看清功夫掺了假，先补被跳过的部分。回头走明路不晚，白花开在枯枝旁边就是证据。", career: "小算盘摆上了台面，同事开始掂量你每句话的成色。主动同步信息，比等败露后再解释体面得多。经手的环节书面留痕，智谋见了阳光才走得远。那两柄留在地上的剑，就补在漏洞最显眼的位置。营门重新为你开时，别再抱着剑绕路走。" }
  },
  {
    id: "sw08", img: "sw08.jpg", arcana: "swords", rank: "8", name: "宝剑八", en: "Eight of Swords", glyph: "🪢",
    upright: { kw: "束缚 / 困局 / 画地为牢", love: "八柄剑围成一圈，剑与剑之间其实留着能侧身的空。蒙眼布是自己系的，走不动多半是吓出来的错觉。手上的绳松得很，先把怕失去的事逐条讲出口。泥地陷住的是犹豫，不是这段关系，抬头看清通往城堡的那条路。每周先在泥地外恢复一件爱好，无力感会退一层。", study: "她认定走不出这片泥地，像认定自己天生学不会那门课。围住的八柄剑数得清，不敢问的那道题才最占地方。蒙眼刷题只会越绑越紧，向老师要一个具体的解答。剑圈外就是湖水与桥，每天只设一个必完成的微任务。别用一句我不行把全身捆住，绳结一拉就开。", career: "流程与压力像剑插成一圈，动一步都怕碰到刃。细看每道限制，纸老虎和真规则往往混在一起。眼睛被布蒙着时，先要一份书面的明文规定再行动。泥地里先守住已有成果，再挑限制最小的口子试一步。城堡的门没有锁，把每条限制验证一遍就知道。" },
    reversed: { kw: "松绑 / 觉醒 / 自解其缚", love: "眼布摘下的瞬间，她发现剑圈一直虚让着一尺。手腕的绳落在泥里，选择权原来从没交给别人。别追是谁系的布，把力气拿去走那座桥。松绑后先想清楚要什么，再决定这段关系的方向。旧绳解了，新捆上的念头也要认得出、推得开。", study: "她迈出泥地第一步，剑圈只是响了一声没拦住。趁这股劲报一次模考，验证一次信念就牢一分。拖延已久的难题集中清一批，正反馈会跟着来。每次求助后记下结果，事实是最稳的松绑绳。桥那头的城堡就是新目标，把我不行改写成还没会。", career: "围了很久的剑阵出现一道缝，僵住的局面有了出路。别在原地反复量那几步，联络靠得住的人趁窗口迈步。眼布一摘才发现，多数限制是自己默认签下的。计划拆成本周可见的进展，松动就坐实成结果。走出泥地后回头复盘成因，别再走进同款剑阵。" }
  },
  {
    id: "sw09", img: "sw09.jpg", arcana: "swords", rank: "9", name: "宝剑九", en: "Nine of Swords", glyph: "😰",
    upright: { kw: "焦虑 / 噩梦 / 午夜忧思", love: "墙上九柄剑，多半悬在自己吓自己的念头里。深夜反复回放那句重话，天亮看其实没那么锋利。别让一次争吵在墙上挂成九次判决。把担心说出口给对方听，剑就少悬一柄。窗外的月与城还在，情绪的暗屋困不住人。", study: "越临近大考，墙上的剑越像没复习完的清单。焦虑最怕具体：把担心的科目一柄一柄写下来。写下来你会发现，能解决的多过吓人的。熬夜刷题是把剑磨得更亮，睡够才收得住。蛇与绳套都是幻象，你的实力比它们结实。", career: "还没发生的坏结果，已在墙上挂满九柄。复盘只复盘能改的，其余的剑请摘下来。别在深夜回复要紧的消息，凌晨的判断带着刃。把最坏情况写成一页纸，焦虑就从悬着变成可办。天亮后窗影会淡，压力不会永远挂满这面墙。" },
    reversed: { kw: "释负 / 求援 / 晨光破夜", love: "九柄剑开始松动，说明你终于肯开口求助。手从脸上放下来，关系才看得清彼此的脸。旧账不必一柄一柄数完，先抽走最悬的那柄。睡不好的那几天，别急着做任何感情决定。天快亮了，把最想说的那句话留到早晨。", study: "焦虑峰值已过，剩下的剑是惯性在响。把错题本合上睡一周，再打开时剑都落了鞘。敢问出口的那一刻，墙上的蛇就不再吓人。状态回升时先补最基础的一门，稳住手感。把怕考砸换成去做题，念头就让位给行动。", career: "最难的阶段在松动，别在黎明前自己撤岗。向同事开口分担，绳套自己解不如找人搭手。把深夜的恐慌留成笔记，白天逐条销账。犬首猪头般的闲言，摘下来就轻了一整面墙。危机过去后，把这套失眠流程写进预案。" }
  },
  {
    id: "sw10", img: "sw10.jpg", arcana: "swords", rank: "10", name: "宝剑十", en: "Ten of Swords", glyph: "🌑",
    upright: { kw: "谷底 / 终局 / 触底反弹", love: "十柄剑落进后背，黑布盖住全身，结束已经发生。别趴着追问谁错得多，先把自己从这段夜路上扶起来。天边的金光和帆影说明，谷底的另一面是出口。背上插剑的日子只安排吃饭睡觉，别急着起身谈对错。给这段经历写一页收尾，像拔掉最后一柄剑再起身。", study: "成绩崩到不能再低，旧路子的碎片像剑插满后背。推翻要干净，资料、方法、带路的人一次换一轮。黑夜压着海面，重建从最基础的模块起，慢是正常的。那轮日出给对照期指路，新旧方法比一个月再定。先把人从地上扶起来，复盘分清环境、决策、执行各占几分。", career: "方案夭折或被迫离场，十柄剑齐齐落下，没有更坏的了。允许自己趴着丧三天，第四天再动拔剑的活。夜海尽头有船起帆，可迁移的技能和人脉先盘点。天再黑也向着日出，谷底只剩向上的方向，挑一条小步起步。复盘写到归因层，别把十柄剑都算成自己的错。" },
    reversed: { kw: "复苏 / 拔剑重生 / 拒绝躺平", love: "背上的剑一根根拔出，还疼着，人已经翻了个身。别把拔下的剑再插回去，往事不必反复开庭。旧痛复发像夜里回潮，不代表要走回那片黑。对方再示好时，先看剑有没有真的放下再开门。帆影已经到海心，疗愈和决定各走各的节奏。", study: "剑拔到第七柄，成绩抬头，旧坑都变成了路标。把教训写成清单贴在桌前，像标出剑落过的每个位置。剑痕还在背上，回升期忌报复性加量，按计划稳步加难度。天光落在海上，错题重做一遍比熬夜三小时管用。背上的剑痕留作提醒，别留成不敢下笔的顾虑。", career: "天幕裂开一道光，手里的活从冲锋改成止血缝合。翻身的船要等日出才起锚，先修关系与身体。起锚前把漏洞的补救讲给关键人听，先重建信任。东山再起像小船先在近海试帆，别一次押上全部。夜里插过剑的地方都结了疤，节奏比从前稳才算起来。" }
  },
  {
    id: "sw11", img: "sw11.jpg", arcana: "swords", rank: "page", name: "宝剑侍从", en: "Page of Swords", glyph: "🔍",
    upright: { kw: "好奇 / 侦查 / 消息刺探", love: "当你想知道对方的心意，先稳住想冲上山坡的冲动。山顶双手竖剑的少年提醒你，观察本身无错，关键在方向指向哪里。动态里的线索像谷底的河，看得清流向却听不到水声。挑个自然的时机开口，把攒下的疑问换成一次坦率的交谈。好奇是好事，留一分俏皮给面对面的相处，真实的答案在对话里不在页面里。", study: "新知识像天上被风推着走的云，越追越多。每天只锁定一个小主题，像双手握剑那样专注，一米的深挖胜过十厘米的广撒网。十个窗口同时打开，比不上把一处疑点彻底读透。给每个疑问设一个止盈点，找到核心答案就收剑。零散的发现当天归进笔记，像路边的石块码放整齐，信息才会沉淀成知识。", career: "新讯息随风而至，先核实来源再决定行动。侦查的价值在于站在坡顶看清局势，不在复述谷底飘来的闲话。传闻到你为止，就像披风被领口的圆扣拢住。把好奇心的锋刃对准行业情报的系统整理，敏锐用对地方很快见价值。多问一句依据与渠道，消息才能变成可用的判断。" },
    reversed: { kw: "多疑 / 嘴快 / 空谈八卦", love: "疑心一起，就像风把云层越吹越乱，越查越慌。偷看的手机屏幕不是该双手紧握的那把剑，划到深夜只剩自己吓自己。翻到的所谓证据多半经不起列举，如同被风吹弯的树被当成敌人。把疑问摆上台面问一次，比暗中侦查百次更让自己安心。开口质问之前先默问三遍，对方值得你一次坦诚而非一场审讯。", study: "收藏的经验贴堆得很高，像天上的流云壮观却没落雨。浅尝辄止等于站在坡顶朝空挥剑，看着勤奋实则没入土。挑一份最薄的核心资料精读，一次深想胜过十次浅看。限定输入源，站稳脚下的山石再眺望远方。读完用自己的话复述要点，检验这把剑是真归了鞘还是仍在半空。", career: "嘴快把失真的传闻散出去，口碑跌得比山坡还快。转发之前先过来源、证据与职责三道关口，缺一就闭口。四面吹来的闲话像风里的草，别把弯腰的草当作情报。已传出的失真消息要主动更正，越早澄清对信誉的损失越小。空谈像朝空挥剑，把调查落地成书面结论，敏锐才配得上岗位。" }
  },
  {
    id: "sw12", img: "sw12.jpg", arcana: "swords", rank: "knight", name: "宝剑骑士", en: "Knight of Swords", glyph: "⚡",
    upright: { kw: "疾进 / 锐气 / 雷厉风行", love: "直球式的坦白像高举过头的宝剑，痛快却可能吓退对方半步。摊牌之后给这段狂奔留一段缓冲，让对方有上马回应的时间。快是本事，肯勒缰倾听的人更容易赢得真心。约一次节奏慢下来的相处，听听马蹄之外的声音。盾牌上的星徽是诚意，适时把守护亮出来，比剑锋更打动人。", study: "冲新题的势头猛如奔马，思路利落下笔果断。粗心丢的分往往摔在脚下的裂地上，检查环节放慢十分钟就值得。连冲三天勒马一次，把错题与草稿归拢干净。状态好的时段专攻难点，天边乌云压来时就用来回顾旧账。蹄印扬起的尘土散尽后，留下的正确率才是真速度。", career: "改革如奔马过原，积弊一口气扫掉大半，效率肉眼可见地抬升。冲锋前确认人手与资源跟得上马速，快才踩得住实地。受影响的合作方逐个沟通过，阻力会像被风按弯的树服软。举星徽盾牌般守住名声，每拿下一个节点做一次小结。让快有依据可查，冲劲才能守成成果。" },
    reversed: { kw: "冒失 / 攻击 / 横冲直撞", love: "带气的话像脱手的剑，没中靶先伤了最亲的人。马蹄最快的时刻逼对方表态，多半连人带马一起翻车。锋芒收三分再开口，诚意从来不需要靠音量说话。若真伤了人，认真道歉比解释一百句理由更要紧。火气上头时先离开这段狂奔十分钟，回来再谈，路会好走很多。", study: "赶进度翻答案，漏洞全在脚下的裂地里。求快的结果是空，锋芒还没伤敌先扎了自己的脚。每天划出一段固定时间只复盘旧错，不碰新题。错题归类补强，把裂地踩实了再谈提速。正确率先站稳，再去抽马加鞭，这个顺序不能反过来。", career: "横冲直撞地推事，事情是快了，沿路的同盟却得罪了一圈。开口前默问一句，这是为事还是为气。克制不是慢，是把冲下来的成果守得住。把异议者变成商量对象，盾牌这时比剑好用。冲刺计划留出调整余地，给团队上马跟进的时间，盟友才不会沿路散场。" }
  },
  {
    id: "sw13", img: "sw13.jpg", arcana: "swords", rank: "queen", name: "宝剑王后", en: "Queen of Swords", glyph: "🧊",
    upright: { kw: "清醒 / 洞察 / 界限分明", love: "心事像王后面前湖面映出的雪山，清醒而不含糊。丑话说在明处，边界清晰的人反而更让人敢靠近。立界限的时候补一句背后的在意，冷硬的话也就有了温度。摊开的左手是接对方好意的，不只是用来握尺子的。偶尔放下竖起的宝剑分享一次柔软，清醒之外还真实，才更让人心动。", study: "每门课的脉络理成一张清爽的网，像湖水通着雪山那样分明。独自攻题虽强，把思路讲给别人听，输出的准确度会再上一层。分析的严密如宝座上的蝶形浮雕，每一刀都有位置。留一格给直觉灵光，随手记下偶然一闪，不必条条先过逻辑。右手竖剑的姿势提醒你，审清题干再落笔。", career: "裁断是非凭依据讲规则，反对的人也心服。让当事人把话讲完再落剑，程序公道胜过结论正确。锋芒里留一分温度，敬你和亲你才能并存。椅背上的小鸟是个信号，沉稳之处才有真消息敢接近你。主动带一带新人，威信会随善意一起累积，耐久不衰。" },
    reversed: { kw: "尖刻 / 冷漠疏离 / 一刀切", love: "旧伤化作刃，一句刻薄话逼退一个真心人。冷语该是绷带，不该长成嘴角常挂的武器。察觉自己在试探对方时，直接说出需求比刺出去管用得多。伤口养好后，从接住一件小好意开始练习，再温和地开口一次。竖得再直的宝剑，也不该把剑尖指向家门口的灯。", study: "揪着细节瑕疵推翻整本教材，分析变成了内耗。批判前先问这个细节是否影响结论，不影响就记下继续推进。顺着主线先完成一遍闭环，再回头修剪枝节问题。定一个完稿时间，到点先交出去再慢慢打磨。该把批判眼光先入鞘，等稿子真正在手时再拔剑。", career: "标准高到容不下失误，同伴的好意也被呛回来。提意见时附上已认可的部分，对方才真正听得进去。把高标准公开成可执行的细则，苛刻就会还原成专业。威信是带出来的，不是单靠罚出来的。一刀切所有人像朝座边的花挥剑，砍掉的偏偏是潜在的同盟。" }
  },
  {
    id: "sw14", img: "sw14.jpg", arcana: "swords", rank: "king", name: "宝剑国王", en: "King of Swords", glyph: "🏛️",
    upright: { kw: "公断 / 理性 / 权威裁决", love: "争执讲逻辑，承诺算数，日子稳得像崖前的瀑布顺流而下。左手托着的圆球是责任，接了就稳稳托住，风浪来了也不撒手。偶尔放下道理认领一次情绪，压舱石也要有温度才暖人。定期问一次对方的感受，规则之外还需要感受来校准方向。重大分歧交给逻辑梳理，日常的情绪记得先接住再讲理。", study: "跟方法严谨的引路人训练思维，体系像瀑布一样逐级成形。笔记以问题为纲整理，多问一层为什么再往下挖。框架是王冠而非枷锁，戴上它也要记得抬头。定期做一次脱离框架的自测，检验方法是否长在了自己身上。留一处自己的疑问深挖下去，那是你的思辨生根的地方。", career: "决断凭规则与证据，不被情绪和私谊带偏。把裁决依据适度公开，下属执行时才不至于只猜结论。裁决前听听一线执行的难处，剑要冷，握剑的手不能冷。多解释一句裁决背后的考量，追随者会更安心。托球与执剑并重，一手管全局一手管分寸，大盘方向才稳得住。" },
    reversed: { kw: "严苛 / 权术 / 铁腕压制", love: "每场争论都赢在道理上，对方的心却一寸寸凉透。逻辑从来不是感情的替身，王冠暖不了冷掉的炉灶。赢了理试着输一句软话，认领对方的感受。察觉对方沉默时主动停下追问，先承认自己语气过硬。日常留一段不谈逻辑的相处时间，让感受也有声音。", study: "标准答案被奉为铁律，思考的空间越来越窄。别怕挑战权威观点，把依据找足再落笔。参考答案之外列一条自己的解法，对比两者的优劣。被驳回的疑问写成书面问题，用扎实依据争取讨论空间。钻牛角尖就像崖顶那株枯树，挺得笔直却不再发新芽。", career: "规则与权术混着用，表面噤声的团队早已暗流涌动。察觉没人再提反对时，开一次只听取不裁决的沟通会。权力边界写清楚，透明的规矩自会替代铁腕的威压。真正坐镇全局的人，不必靠威慑来立威。手里的圆球象征权威，拿来压人就是用反了它。" }
  },
  // ===== 星币 Pentacles (pb01 - pb14) =====
  {
    id: "pb01", img: "pb01.jpg", arcana: "pentacles", rank: "A", name: "星币王牌", en: "Ace of Pentacles", glyph: "🪙",
    upright: { kw: "机遇 / 种子 / 财富起点", love: "出现的缘分像云中巨手递来的金币，质地厚实，只是场合看着平淡。别因不够惊喜就松手，踏实的对象最经得起细看。把相处当泉水养花，按时赴约认真回应，信任自会生根。热恋滤镜褪去之后，再看看对方的金钱观与责任感。第一枚币落进土里，发芽靠的是往后日复一日的照料。", study: "新资源到手，先看清它值不值得深耕。头一个月打基础养习惯，像泉池先蓄满水，花才有得浇。贪多嚼不烂，专注一门课做出成绩，光才会向一处聚拢。实操型的内容先动手跟练，比纯啃理论见效快。学期中段的检验来得突然，前松后紧的话，补救的成本会明显上升。", career: "眼前的邀约或启动资金，值得认真做一份收支测算。第一笔入账的去向几乎决定后续格局，先留储备再谈扩张。跑通最小闭环，验证模式比铺开规模更要紧。别被光环晃了眼，落地的条款才是这枚币的成色。把这笔机遇当种子栽培，财势的苗才接得住后面的风雨。" },
    reversed: { kw: "错失 / 空想 / 根基未立", love: "把缘分当彩票刮，到手的好意也被嫌不够惊喜。云开处递来的金币只闪一下，盯不住就错过了。眼前的实在人值得放在心上，定期见面，比等待心动更靠谱。总期待更好的出现，会对现在的示好提不起回应的心思。写清楚择偶标准，一次只经营一段关系，踏实感才会慢慢回笼。", study: "课买了资料囤了，种子悬在半空迟迟不落土。拖延的根源常是目标太大，把任务缩到当天能完成的量才动得手。从手头最薄的一本开始读完，进度会帮你找回掌控。先建立最小的学习记录，看见自己在走，动力才跟得上。眼高手低荒掉的不只是机会，还有土壤本身的肥力。", career: "听着诱人的项目往往账目含糊，回报承诺越响越要多问一句凭什么。先用小额投入试水，看清对方信用再谈大额进入。高收益话术常用时间差掩护风险，问清回款节点才看得见成色。错失不必懊悔，把手头的小账管出章法，根基立起来才接得住下一班船。悬在半空的金币不会自己落地，伸手的人才配谈收获。" }
  },
  {
    id: "pb02", img: "pb02.jpg", arcana: "pentacles", rank: "2", name: "星币二", en: "Two of Pentacles", glyph: "🤹",
    upright: { kw: "周转 / 弹性 / 收支平衡", love: "各自忙碌的阶段，靠的不是黏在一起，而是把相处认真排进日程。两枚币要轮着抛，见面的频率与共同开销摊开商量，弹性比硬挤长久。忙闲节奏不一致时，把想见的心思提前说出口。一起建个共同账户也好，钱有目标，日子才有方向。礁石上的舞步乱了不要紧，绳环还在，重新对拍就行。", study: "几门功课同时推进，按难度与截止日期动态分配时间。给弱科多留一格缓冲，别把最基础的科目挤到浪边。日程排满也留一格机动，临时加塞的任务先评估能否延后。进度滑坡几天很正常，看整阶段的曲线，别为单日起伏自乱阵脚。两枚币交替的诀窍不在手快，在眼睛始终盯着落点。", career: "同时接手几摊事，靠的是随时重排优先级的手感。最影响收入的那条线先守住，其余的轮着抛。留出余力应对意外，账面再顺也别把现金流排得太满。两份进账分账管理，哪头养主业哪头可取舍，分得清才守得住。浪头一高一低是常态，绳环画得圆，周转就不断。" },
    reversed: { kw: "失衡 / 超载 / 拆东补西", love: "时间被应酬占满，留给伴侣的只剩疲惫和敷衍。抛着抛着一枚币落了地，冷落就是这样开始的。把关系也当成必须排的账，每周固定留一段不被打扰的时光。抱怨对方缺席之前，先摊开日程表看看时间被什么占据。哪怕只有一顿专心吃饭的陪伴，也胜过心不在焉的整天相处。", study: "摊子铺得太大，几门功课都停在半熟。贪多的背后是怕落后的焦虑，承认精力有限反而是减负的开始。砍掉一门暂缓一门，集中火力先啃下一科。按考试的远近重新排序，最不急的先放一放，压力立刻可控。脚下礁石本就窄，别再往绳环上多挂一枚币。", career: "几个项目互相占用预算，拆东墙补西墙越转越吃力。先把账目列清楚，停掉回报最弱的一头，周转的空间就回来了。透支的账不会消失，只会连本带息延后到期，越早面对越主动。进度撑不住就坦率说明，遮掩最伤信用，坦白反而能换来宽限。船在浪里偏了航向，先收绳，再重新起势。" }
  },
  {
    id: "pb03", img: "pb03.jpg", arcana: "pentacles", rank: "3", name: "星币三", en: "Three of Pentacles", glyph: "🔨",
    upright: { kw: "协作 / 匠艺 / 专业认可", love: "石殿里三人各司其职，好的感情也靠分工成全。有人画图纸有人执锤，把各自擅长的那段做扎实。别让人只跪着许愿，起来一起凿才看得见进度。被夸的那块石头不会自己成形，功劳要分给同路人。拱顶三枚金币亮着：认真经营的关系自带光彩。", study: "像图纸与石料对上号，方法对了苦功才有形状。把大目标拆成一日一凿，拱门就是这样合拢的。请教老师如展卷核对，别自己闷头把石头凿歪。小组里认领自己的那根石柱，分工清楚效率自现。光从窗里照进来，你的进步也需要被人看见。", career: "匠人、图纸、跪地者，三方到位工程才动土。手艺被看见的起点，是把交付做成可检验的样。提案前先对齐图纸，返工是最贵的协作成本。别抢凿子的活也别攥着图纸不放，各就各位。三枚星币悬在拱心石上方，成果要挂在明处。" },
    reversed: { kw: "返工 / 扯皮 / 各干各的", love: "图纸对不上凿子，两人的规划从一开始没摊开。一人跪着许愿一人闷头凿石，努力不在同一面墙。敷衍的活糊得上表面，糊不上接缝。先停下来核对图纸，再谈谁凿得不够。别用加班式的补偿掩盖方向的错位。", study: "方法没对齐就猛凿，越努力越像返工的预备。笔记厚如图纸而手上无活，眼高手低是病根。找老师当面批改，比独自猜图纸快得多。小组分工不均时先补位再追责，工程最怕停。拱顶的币暗下去，是进度在提醒你先对标准。", career: "三方各凿各的，墙砌歪了才想起看图纸。交付经不起验收，口碑比返工更贵。别把糊弄的模块藏进整体，接缝迟早开口。重新开一次对齐会，把图纸投影在墙上。手艺不精就先认，拜师比硬撑省时间。" }
  },
  {
    id: "pb04", img: "pb04.jpg", arcana: "pentacles", rank: "4", name: "星币四", en: "Four of Pentacles", glyph: "🔒",
    upright: { kw: "守成 / 储蓄 / 稳握资源", love: "安全感是一格格存下来的，不必羡慕别人的惊喜。守住之余也要舍得表达，别让稳定被误读成不上心。固定存一笔共同基金，是实在的浪漫。偶尔安排一次超出惯例的小用心，稳定才不会过成例行公事。怀里的金币再暖，也别忘了抬头看看身边人的眼睛。", study: "防守型打法自有甜头，把已会的题型反复夯实。定期回顾旧笔记，地基越牢，后劲越足。每次模考后把失分点归档，守住基础分的本钱就在这些记录里。不冒进不贪难，先把出现过的内容吃透，胜过泛泛刷新题。脚边踩着的那枚也别忽略，基础分最怕从脚下松动。", career: "现金为王的阶段，把钱和人脉都攥在稳妥处，波动里你最抗跌。保守不等于不动，留少量试水额度，机会来了也有船票。趁账面稳定清点家底，收支合同库存盘明白再谈扩张。守成太久容易错过升级窗口，每年划一笔学习经费。头顶那枚币别让它滑下，站稳了才守得住四方。" },
    reversed: { kw: "吝啬 / 撒漏 / 松手的功课", love: "金钱和情感都算得太精，对方觉得自己像在借据里生活。账算得越清，两颗心离得越远，爱本来就没法精确对账。试着松一松手指，主动给一次不计回报的付出。先从一件不计价的小事做起，接一次下班，做一顿饭。怀里的币攥得再紧，也留一枚递到对方手里。", study: "资料舍不得删方法不肯换，越囤越乱反而妨碍吸收。给笔记做一次取舍，只留主干勤做输出，知识才能盘活。囤积是安全感的替代品，真正吃透一页胜过收藏十份。定期清掉用不上的材料，轻装上阵之后复习效率自会回升。脚下踩着的那枚最危险，它挡着你往前走的步子。", career: "要么大手大脚漏财，要么一毛不拔凉了同事的心。设一条固定的储蓄线，同时在人情往来上留出合理预算。漏财要先找出口，把固定支出逐项过一遍，大头常藏在损耗里。人情预算别一刀切砍光，省下的钱迟早要拿关系偿还。石凳本就冰凉，别再把自己坐成一座雕像。" }
  },
  {
    id: "pb05", img: "pb05.jpg", arcana: "pentacles", rank: "5", name: "星币五", en: "Five of Pentacles", glyph: "❄️",
    upright: { kw: "困顿 / 匮乏 / 风雪同行", love: "经济吃紧时，最容易把焦虑撒向最亲的人。难处摊开一起面对，两人共撑一段雪路总好过各自挨冻。低谷期最忌互相埋怨，把困难当成两个人共同对付的外敌。手头紧也可以有心意，肯分担本身就是熬过冬天的本钱。彩窗的光已经照在雪上，别低头只数自己的脚印。", study: "缺资料缺指导时，硬扛闭门最熬人。鼓起勇气敲开一扇门，援手往往就在彩窗亮着的地方。一次请教可能少走半个月弯路，别把求援当成丢脸的事。经费缺口坦率摆出来申请，愿意伸手的人比想象中多。雪夜里先看清光从哪扇窗透出，再决定往哪边走。", career: "行业寒冬里人人自危，愿意递机会的人格外珍贵。坦率求助并记下这份善意，渡过难关后郑重回谢。保住现金流比争面子要紧，能屈能伸才有翻盘的资本。求助时把打算说得具体些，有规划的人更容易被拉一把。杖要拄稳，两个人挨着走，这段雪路就没那么长。" },
    reversed: { kw: "脱困 / 求援 / 看见窗内光", love: "最难的日子彼此没走散，窗内的光终于照到了两人身上。记得感谢对方的坚守，苦尽之后的感情更懂珍惜。回暖初期别急着翻旧账，先一起庆一庆没散这件事。把共渡难关的经过讲开，下次再有风浪，两个人都知道怎么撑。雪在化，把对方的手从兜里拿出来牵着走。", study: "接受的指点开始见效，落下的进度正一点点追回来。把补漏的方法沉淀成笔记，趁势建立自己的求援网络。补漏最忌贪快，每补上一块就做一次输出，才算真正焊牢。带你入门的人值得常联系，学业上的援手常常延续成师谊。回头看那扇亮过的窗，它就是你下次求援的路标。", career: "被拒多次的门终于松动，转机常是一笔小单或一次引荐。带着体面与感恩进场，回升期最看重一个人的信誉。转机初现先小步验证，别因一笔订单就急着加杠杆。困难期许下的承诺记下来，好转后逐一兑现，路只会越走越宽。杖可以放下了，前面的雪路已经走出了脚印。" }
  },
  {
    id: "pb06", img: "pb06.jpg", arcana: "pentacles", rank: "6", name: "星币六", en: "Six of Pentacles", glyph: "🤲",
    upright: { kw: "给予 / 资助 / 收支对等", love: "红衣人举着铜天平先称轻重，再伸手递币，付出也该有这杆秤。给出去的关心像递到乞者掌心的那枚星币，要看着对方的手接稳。两位跪地的人一个合十一个抚胸，接受好意的姿态本就各不相同。别把对方的付出当成地上散落的三枚币，俯身捡起前先道一声谢。爱情讲收支对等，这周你多走一步，下周就该换他主动上门。", study: "天平举过头顶的那只手提醒求学者，受人资助先量清自己欠的分量。前辈递来的资料就是掌中那枚星币，接住后要把它磨成自己的手艺。跪地合十不妨学一分诚恳，请教时把卡住的具体步骤说清楚。得到五分的帮助，还出三分整理好的笔记，流动起来才不会干涸。每月留一次回馈的额度，给后来者指路，也逼自己把知识盘活。", career: "资助方举秤如红衣人，审的是投入产出，你汇报时也该带这杆秤。拨款落地先立一张明账，每笔开销对应地上那几枚币，枚枚有去向。接受支持时学那位抚胸的乞者，把手放在心口，把感激说在当面。项目结项后主动让利新人，天平两端轮流承重，资源才肯继续流向你。下一次争取预算，把回报周期与分配方案写在一页纸上递出去。" },
    reversed: { kw: "不对等 / 附带条件 / 索取无度", love: "铜天平一旦歪了，递出的每枚币都成了压人的砝码，爱情同理。总跪着接币的人会逐渐习惯仰视，付出多的一方也别站得太高。慷慨若像悬在半空等跪谢的手，先把币收回来，说清来意再给。把账摆到明处谈，谁长期单方面输血，谁就该先坐下歇一歇。要求回报不算失礼，把帮助标好利息慢慢逼对方低头，才是伤人。", study: "借来的笔记若只抄答案不抄思路，等于拿了星币却丢了那杆秤。伸手要帮助之前，先把自己卡住的位置指给对方看。资料分配明显偏心时，沉默只会把失衡坐实，如实提出来更好。靠别人拖进度，就像跪地的姿势，久了腿会麻，路也走不直。每学期设一笔自学的预算，减少对外援的依赖，秤砣才回到自己手里。", career: "带条件的拨款像悬在半空不肯松开的币，接之前先问清义务。拿人手短的后患，是往后每次抬头都要先看递币那只手的脸色。团队分资源时天平长期偏向明星项目，坐不住的其实是干活的人。把援助换算成白纸黑字的条款，人情账走不远，明账才走得长。发现自己只在输血不会收账，就把慷慨设个额度，到期停一停。" }
  },
  {
    id: "pb07", img: "pb07.jpg", arcana: "pentacles", rank: "7", name: "星币七", en: "Seven of Pentacles", glyph: "🌱",
    upright: { kw: "等待 / 评估 / 长期主义", love: "扶杖的农夫仰头看藤上的币，果实未熟，急也急不来。感情里的藤蔓正在土里扎根，地表看不见动静，不等于没有生长。别天天拨弄叶子查岗，像他那样双手叠在杖顶，隔些日子再看一眼就好。暮色落在石墙上，今天浇完水就收工，留点期待给明天。约好每季度聊一次进展，把长线的耐心换成看得见的复盘。", study: "七枚星币挂在一根藤上，背完一章再摘一枚，进度要数得清。倚杖远望的姿态值得抄进计划：埋头苦读之外，定期抬头评估方法。投入换不来分数时先查枝剪叶，分清是方法错了还是时候未到。量变到质变之间最熬人，给自己定一个秋天的验收日。远山不动，人也不慌，把大目标拆成每月一枚小币慢慢摘。", career: "投资像那株爬藤，账面平淡的月份，根系正往石墙下延伸。农夫没有摇树催果，回收期里少做小动作，多记观察笔记。设一个明确的评估节点，到期对照数据决定补投还是收手。杖不是用来戳果子的，是撑着人站稳的，等的时候把身子守住。那道远山提醒操盘者，行情有季节，长期主义按季结算。" },
    reversed: { kw: "焦躁 / 歉收 / 及时止损", love: "藤上的币迟迟不落地，倚杖的人开始怀疑这片土，感情最怕这种耗法。单方面浇水的人委屈是真的，把委屈说出口，别让它烂在根里。在心里划一个期限，到期仍不见回响，就体面地放下那根杖。石墙内的园子再熟也不是你的，先看清是树慢还是地薄。止损不是认输，是把余下的时间和钱留给会结果的那株苗。", study: "数来数去还是七枚币挂在原处，加量的时间换不来产量，就该停一停。别学那个仰头长叹的姿势，愁完把错题摊开，查是理解断了还是练习虚了。有效学习时长先测一遍，砍掉藤上那些空叶，两小时专注胜过十小时空坐。方法换掉后会进新的平台期，刚改就催结果，等于新栽的苗又被摇松。实在确认方向不对，及早换赛道，攒下的基础大多能打包带走。", career: "藤蔓上看着有币，摘下来全是瘪的，歉收的账要趁早摊开算。沉没成本像缠住杖尖的枯藤，越拽越紧，先承认亏损才能松手。把盈亏线画在纸上，到期不达就砍投入，犹豫的成本按天计息。占着资源不结果的项目，和石墙下疯长的野藤一样，会绞杀别的苗。转方向前先盘点手上的人脉与手艺，农夫换地，农具还是自己的。" }
  },
  {
    id: "pb08", img: "pb08.jpg", arcana: "pentacles", rank: "8", name: "星币八", en: "Eight of Pentacles", glyph: "⚒️",
    upright: { kw: "精进 / 匠心 / 熟能生巧", love: "錾星的手一下一下不落空，感情里的浪漫也藏在重复打磨的小事里。记住口味、修好门锁、按期交心，把例行小事做稳就是手艺人的深情。墙上六枚成品币都是一锤一锤攒的，别嫌日子单调，枚枚都算数。每周留一晚共同打磨一件事，做顿饭或收拾角落，比节日大礼更沉淀信任。各自精进之余别忘对视一眼，锤声再密也要留出说话的间隙。", study: "工匠低头盯的是掌中那枚币，刷题时一次只锁一种题型，吃透再换。案上夹具备着下一枚坯料，错题也该夹进固定册子，定期取出来重錾。六枚挂墙的成品就是进度条，记下每天真正錾深的部分，别只数坐了多久。工具架上锤凿各归其位，笔记、错题、真题分开放，找起来才不耗神。阶段末拿模拟卷验一验火候，闭门錾得再美也要经得起外头的眼光。", career: "不抢风头的围裙工匠靠交付攒口碑，一件件扎实活儿就是墙上的币。每单收工留三条心得，攒到一定数量，机会会自己循着锤声找上门。报价按工时算清，錾一枚币要几锤，做一件事要几晚，心里先有账。带一次新人或做一场分享，教人握锤的过程会逼你把门道说透。酒香也怕巷子深，作品挂到能被看见的墙上，精进才换得来回报。" },
    reversed: { kw: "懈怠 / 机械 / 敷衍了事", love: "锤子若不过脑地空落，星币錾不出花纹，走过场的关心也焐不热人。纪念日照抄去年的流程，像机械翻动同一枚旧币，少了新錾的花样。停下想想当初为何出发，做一件超出惯例的小事，先把锤声敲出新节奏。哪怕墙上六枚币蒙了灰也没人察觉，倦怠要说出来，别让两人默默硬撑。把应付的打卡换成一次真诚长谈，手艺生疏能练，心懒了要先唤醒。", study: "笔记抄得工整如模具压币，错题却还是老几样，机械勤奋骗不过考场。专攻錾不深的那几枚，把时间砸在不会的部分，难一点才是真打磨。换个书房或换种题型，工坊待久了手会油滑，脑子也跟着偷懒。用自测驱动复习，合上书能复述几枚，才算墙上真正挂住了几枚。状态太差时干脆停工几日，离开工坊再回来，锤落下去才有分量。", career: "赶工交出的毛边币，錾纹浅得指甲一刮就掉，招牌正是这样磨没的。接不住的活儿坦白延期，返工的成本远高过一次诚实的沟通。夹具里的坯料没夹紧就下锤，工序一省，成品跟着歪。倦怠压不住就申请轮岗进修，离开案台一阵，回来才认得清星纹该怎么錾。每月给作品定一次质检日，抽三枚细看錾痕，糊弄的活儿自己会露馅。" }
  },
  {
    id: "pb09", img: "pb09.jpg", arcana: "pentacles", rank: "9", name: "星币九", en: "Nine of Pentacles", glyph: "🍇",
    upright: { kw: "富足 / 独立 / 享受生活", love: "园中女子不等人送花，自己已有满架葡萄，丰盈的人自带吸引力。戴皮手套托着猎鹰，是驯住心气的功夫，爱人之前先管好自己的欲望。园门虚掩着，自足不等于上锁，留一扇门别人才进得来。孔雀在脚边从容开屏，不必炫耀收成，从容的姿态本身就是名片。分摊账单时爽快不扭捏，经济独立让你在感情里敢选敢留。", study: "九枚星币在墙上排得整整齐齐，学有余力的人，知识也自成体系。驯鹰讲究耐心与节奏，温书也一样，按自己的步调驯服最难那门课。独自丰收之余，偶尔走出园门与人切磋，照照别人的镜子。把心得整理成笔记输出，讲一遍胜读三遍，风格在讲述里更清晰。定期用真题检验这套方法灵不灵，葡萄年年熟，架子也要年年修。", career: "华服女子名下的收成都是长年攒的，收入结构健康，才睡得安稳。把盈余像挂币一样稳稳排好，留出半年开销的储备，再谈长线配置。猎鹰在腕而心不慌，接大单前先把风险驯熟，条款吃透再抬手。独立归独立，留一两个合作窗口，园门常开，机会才走得进来。丰盛之余做点长线打算，让眼下的余裕像葡萄藤一样爬向十年之后。" },
    reversed: { kw: "虚饰 / 依赖 / 财务窟窿", love: "袍子再华贵也遮不住空荡的园子，用礼物堆安全感，堆不出真心。摆样子的猎鹰迟早飞走，靠排场确认的爱意同样留不住。直接说出情感上的需要，别把在乎折算成对方买没买单。尾羽华丽却飞不高，物质外壳盖不住内在的匮乏。把重心放回自身积累，园子真丰收了，就不用伸手讨认可。", study: "墙上九枚币擦得锃亮，架上的葡萄却在烂，成绩虚高最怕这种对照。笔记做得像华服一样精致，合上书复述不出几段，就是给眼睛看的功夫。回到最基础的内容做自测，圈出烂果的位置，一颗一颗修剪。别学只会被喂养的鹰，离开答案单飞，才看得出真本事。漏洞补完前暂缓刷新进度，先踏实再好看，顺序不能颠倒。", career: "账面风光如满墙金币，现金流却在悄悄漏，先盘账再谈扩张。面子预算最先砍掉，园门内的烂果不收拾，孔雀开屏也救不了场。对外报价留足实底，虚高的身价经不起一次认真的盘查。依赖平台光环单飞，像没驯熟的鹰上手，爪子一松币就飞了。把窟窿堵好再装饰门面，账本干净，睡得比华服踏实。" }
  },
  {
    id: "pb10", img: "pb10.jpg", arcana: "pentacles", rank: "10", name: "星币十", en: "Ten of Pentacles", glyph: "🏦",
    upright: { kw: "传承 / 家业 / 基业长青", love: "拱门上的十枚星币是家底也是承诺，谈婚论嫁时把它们亮给彼此看。长者闭目坐在门内，长辈的祝福要主动去换，多跑两趟家门。财务安排与家庭边界婚前聊透，像拱门砌石，缝对了才立得久。婚后与两边老人保持一碗汤的距离，体面留住了，摩擦自然少。孩子玩木马，猫狗卧在一旁，把这种日常的画面聊进婚后的规划里。", study: "远处的城堡是家族攒下的基业，前辈铺的路让你少走许多弯路。借势不忘自身用功，把家里的方法与资料消化成自己的习惯。白须者安坐长凳的姿态提醒你，从容来自一代代按部就班的积累。把家族支持当底气而非拐杖，自己的成绩才是最好的回报。每门功课定一条独立完成线，靠山前的石头也要自己搬几块。", career: "十枚币分列拱门两侧，家业的规矩是数得清的，制度先于人情。平台有积累，个人努力站在稳固底盘上放大，选赛道先看地基。用心带教接班人看似分权，实为加固你打下的城墙。大额支出按流程走，像长者闭目也听得见动静，规矩替你守业。把传下来的经验写成手册，让家业靠体系运转，而非靠一个人撑持。" },
    reversed: { kw: "纠纷 / 耗散 / 守业维艰", love: "门上的币数得清，心里的算盘却数不清，婚事卡在彩礼与房本上。两个家庭的争执声里，先听清身边人拥着你说的那句立场。把婚事与房产拆开谈，感情归感情，账目归账目，别烩成一锅。坐在长凳上闭目的老人无暇过问，小两口的分歧要自己先解决。门第之见像远山上的城堡，看着巍峨，不必供在头顶当裁判。", study: "总指望家里兜底的人，坐不稳那条长凳，成绩也撑不起那道拱门。把可用条件列成清单，然后独立规划，靠山也要自己会爬山。资源越是现成越容易瓦解动力，先划一条独立完成线。家族期望与个人方向冲突时，别争辩，拿实打实的成绩说话。木马要自己推才转，学业要自己动手才转得顺。", career: "人情的账压过了经营的账，拱门上的币一枚枚松动，内斗就是这样开头。股权与职责模糊是争端的温床，先定好拍板的人，再谈效率。守业期现金流优先，铺张排场和面子工程最先裁撤。把分配规则白纸黑字写下来，挂在明处，比任何家训都牢。资产缩水时体面最误事，及早止损才守得住祖辈的底子。" }
  },
  {
    id: "pb11", img: "pb11.jpg", arcana: "pentacles", rank: "page", name: "星币侍从", en: "Page of Pentacles", glyph: "🎓",
    upright: { kw: "勤学 / 实操 / 小额机遇", love: "少年双手捧币细细端详，青涩的认真比动听的情话更打人。约会守时、说到做到，幼苗般的感情靠一次次兑现小承诺长大。别急着要名分，像他盯星币纹路那样，先看清对方的人品细节。披风上的叶纹要一针一线才绣得成，感情也要一件一件小事来攒。若心动的人表现笨拙，多给一点时间，心意全在动作里。", study: "学徒捧着星币像捧着全世界的道理，从头练基本功，进度慢些也值得。把实习和访学的机会亲手做一遍，手上的记忆比书本更牢。遇到带教多问一句为什么，模仿里掺进思考才长得成能力。白花满地的园子也要逐株辨认，学习计划切成每天可完成的小块。攒下每单的三条心得，合起来就是你的第一桶学问。", career: "新人接小单如侍从托起第一枚星币，掂量它的分量，也掂量自己的耐心。流程与门道都藏在琐碎事务里，打杂不吃亏。把每件小事做出作品的样子，师傅和机会都在暗处看着你的手艺。主动把复盘记录给上级看，接住的小单会越滚越大。起步阶段别挑肥拣瘦，叶纹斗篷也是一针一线绣出来的。" },
    reversed: { kw: "拖延 / 眼高 / 学业分心", love: "捧币的手若迟迟不伸出去，再亮的星币也照不暖两个人。嘴上说以后会改，日程上却永远排不进对方，期待一再落空。把远期约定拆成本周可见的小行动，做不到的事先少许诺。幼苗经不起没完没了的等待，按时浇水的人才有收成。少说空话多做眼前事，信任这点绿苗才不至于枯在坡地上。", study: "课程收藏了一大堆，手里的星币却从没翻面看过一次。收藏夹不等于书桌，今天就把排第一的资料翻开读十分钟。目标太大就切成十分钟能做的小块，先完成再谈完美。进度不理想时别怪自己笨，回头查哪一步断了投入。花架子计划做得再漂亮，也替不了动手錾下的第一道痕。", career: "眼高的人扫一眼草地便嫌花小，手低的机会就这样从指边溜走。嫌基础岗位委屈，就先交一份超出预期的改进方案。限期把一件小事做出水准，舞台从来是用实力换来的。实操时怕脏怕碎就永远接不住币，师傅不会递第二枚。拖延的账最诚实，错过的那班车会在月底的工资单上现形。" }
  },
  {
    id: "pb12", img: "pb12.jpg", arcana: "pentacles", rank: "knight", name: "星币骑士", en: "Knight of Pentacles", glyph: "🐂",
    upright: { kw: "稳健 / 坚持 / 按部就班", love: "金甲骑士坐在马上不催鞭，慢热的人一旦认定就极长情。他不太会说想你，但加班会报备，答应的事从不落空，像掌中那枚币一样实。给直白的行动多一点回应，老实的深情更需要被看见。稳定的节奏偶尔要仪式提鲜，安排一次小小的出其不意。田垄要一犁一犁地走，日子要一周一周地过，急不得。", study: "白马踏着犁好的垄沟一步步走，固定时间固定计划，把考纲一寸寸啃完。像骑士端详星币那样细看教学大纲，摸清重点再上路。保持自己的节奏别乱攀比，慢就是稳，稳到最后就是快。固定计划里留一格机动，某天状态差也不至于全盘崩塌。每月用模拟考校准一次方向，防止勤奋滑向低水平的重复。", career: "铁甲与盾牌护着的不是锋芒，是一份零失误的交付记录。交给他的事谈不上惊艳，却绝不掉链子，口碑就这样一枚一枚攒起来。适当汇报进度里的亮点，靠谱也需要被人看见。长期项目靠稳定输出取胜，把每日进度做得公开透明。靠谱之余练一次快速响应，关键时刻提速更让人刮目相看。" },
    reversed: { kw: "迟滞 / 怠惰 / 原地打转", love: "马在原地踱步多年，约会的路线和流程早已磨平了热情。乏味未必是感情耗尽，更可能是共同体验久未上新。主动约定阶段性的目标，一起完成件从没做过的事。偶尔偏离熟悉的田垄，绕去没走过的街角，节奏就活了过来。进展慢到像没走时，把话摊开谈，别指望沉默自己会拐弯。", study: "守着旧方法打转，像白马绕着同一块田埂转圈，转得越久越晕。每天坐满十几个小时，来回翻的却还是那几页。停下来重测薄弱环节，升级方法比延长时间更要紧。坐得久不等于学得进，改用结果倒推每天的有效时长。把计时换成计任务量，完成清单比坐满钟点更能说明问题。", career: "工期一拖再拖，犁好的田还没下种，老牛式的稳妥过了头就是迟滞。给交付设好提前量，留出时间试新，别拿稳妥当拖延的挡箭牌。流程走了千百遍不敢改动，新方案新工具就被一拖再拖。延误要先找流程堵点，光靠加班硬扛只会把问题后推。每季度试着换一样新工具，盾牌的纹样也要与时俱进。" }
  },
  {
    id: "pb13", img: "pb13.jpg", arcana: "pentacles", rank: "queen", name: "星币王后", en: "Queen of Pentacles", glyph: "🌻",
    upright: { kw: "持家 / 务实 / 富足的照料", love: "王后把藤椅打理得妥帖，一桌热饭与一份家计清单，就是她的爱的语言。照顾之余也肯示弱，偶尔让对方来照顾你，关系才双向流动。把家务设计成两人搭手的日常，被共同需要的感觉最养感情。猫儿卧在阶前打盹，说明这个家有安全感，功劳该分他一半。付出要留有余地，先把自己这盏灯添满油，再照亮全屋。", study: "黄花冠下的王后深谙环境之道，书桌整洁、作息安稳，学习自然有土壤。把休息与饮食一并排进计划，身体状态直接写在专注力上。像侍弄藤椅上的葡萄那样打理笔记，枝蔓理顺了，果子才结得密。整洁之外留一点弹性，偶有凌乱也不必焦虑自责。状态好的时段留给最难的科目，家务琐事排在末尾。", career: "她持家般管预算，井井有条的作风让上级格外放心。把务实的成果量化呈现出来，柔和的手腕要配上清晰的数据。管家式管理的长处是流程，把经验写成清单交给团队复用。温和不等于没有原则，预算与底线要事先讲在明处。像喂猫喂兔那样按时按量，资源分配有定例，团队才不闹饥荒。" },
    reversed: { kw: "失衡 / 操劳 / 物质焦虑", love: "阶前的猫兔都喂饱了，唯独王后自己眼窝发青，贤惠失衡就成了委屈。家务和操心全揽在身上，对方习以为常，怨气在细节里累积。把隐形付出列成清单摊开，先让对方看见，再谈如何分工。委屈攒多了会变成指责，不如每天说一句真实的感受。操持家务的人同样需要被操持，花冠再金贵，也得有人替你摘下来歇一歇。", study: "杂事和他人的需求挤满日程，书案上的课本蒙了灰，像顾不上打理的藤椅。每天先划出一段不可侵犯的学习时间，其余琐事排队处理。琐事无限膨胀是因为没有边界，给杂务划定固定时段，其余打扰一律延后。生活里最搅状态的那件事优先处理掉，书桌才坐得安稳。先把自己这株花安顿好，再谈照料满园的人。", career: "事事亲力亲为替人兜底，自己长期超负荷，团队反倒学不会走路。列一张不该管的事项清单，把能授权的交出去，才守得住核心。替所有人兜底会养出整个团队的依赖，教会负责才是真省心。账目家务两头难时，先保账本再保体面，其余的乱子塌不下来。对不合理的需求摇头，温和的边界比无底线的热心更长久。" }
  },
  {
    id: "pb14", img: "pb14.jpg", arcana: "pentacles", rank: "king", name: "星币国王", en: "King of Pentacles", glyph: "💰",
    upright: { kw: "稳健理财 / 成功 / 雄厚", love: "国王把星币平摊在掌心，房、账与日程都安排妥当，这是他的担当。享受安稳也别忘了谈心，物质之外再留一点柔软的位置。把家庭计划像经营事业一样写进日程，定期逐项对齐。满桌大餐不如一次眼神交汇的家常饭，人在场才是关照。财富是给家的底气，用心的陪伴才是传给家人的真资产。", study: "头戴嵌宝石王冠的人懂得，平台与资源是拿来成事的，不是拿来躺的。每月给自己定一个交付期限，把平台给的便利压成真本事。借人脉请高人指点，再把指点消化成自己的功夫。管理式打法适合冲刺期，给每个目标定责任制与时间表。园圃修剪得整整齐齐，错题与笔记也要定期归置，用时才找得到。", career: "牛头扶手的王座坐得稳，靠的是多年判断准、出手稳的信誉积累。守业更要带新人、建制度，让成功可以复制和延续。版图越大越要把情分与利益分开，让制度去批账，别靠个人圣裁。定期拨一笔长线预算，雄厚家底要用在十年后的赛道上。越成功越要留出分享与公益的一席，格局决定最后的上限。" },
    reversed: { kw: "贪婪 / 固权 / 铜臭短视", love: "金库越砌越高，家里的对话越来越少，礼物代替不了人缺席的晚上。从日程里挪出一整晚留给家人，温度比排场更能养感情。把财务安排适度向家人透明，信任比金库更值得加固。攥紧钱包的手也攥紧了控制权，爱意会在高压下悄悄退潮。王冠再沉，也沉不过一句长期说不出口的软话。", study: "条件好反而松懈，成绩看着体面，底子全靠平台撑着，如铠甲下的虚胖。趁早做几次从零开始的自测，把资源真正炼成自己的功力。真本事要能离开王座自立，用裸考式成果检验自己才作数。给自己设一段断奶期，独立跑通一个课题才见真功力。躺在资源清单上数金币的人，账上的数字不会变成脑子里的本事。", career: "对新市场和新人都戒心过重，把持得越紧，流失得越快。也要拨一笔试错预算，舍得布局的人才守得住大版图。恋栈权力越快，愿意追随的人走得越早，适时放权反而更稳。短视的贪念常始于一次违规操作，守住合规底线等于保住版图。把既得利益当成牛头扶手死死不放，迟早被它顶下王座。" }
  }
];
